  if (!option.topColor || !option.bottomColor) return option;
  return {
    ...option,
    topColor: {
      ...option.topColor,
      hex: TOP_BOTTOM_PALETTE_SWATCH_HEX[option.topColor.en],
    },
    bottomColor: {
      ...option.bottomColor,
      hex: TOP_BOTTOM_PALETTE_SWATCH_HEX[option.bottomColor.en],
    },
  };
}

