function buildEntries(groupName, groupedData, inferMeta, captureInference = false) {
  return Object.entries(groupedData).reduce((acc, [category, items]) => {
    acc[category] = items.map((item, index) => {
      const rawZh = stripMarkdown(item.zh);
      const displayZh = formatWardrobeOptionDisplayName(category, rawZh);
      const legacyId = `${groupName}:${slugify(category)}:${slugify(rawZh || item.en || String(index))}:${index}`;
      const ambientLightLegacyIds = groupName === 'camera' && category === AMBIENT_LIGHT_CONDITIONS_CATEGORY
        ? [`${groupName}:${slugify(LEGACY_ENVIRONMENT_MOOD_CATEGORY)}:${slugify(rawZh || item.en || String(index))}:${index}`]
        : [];
      const normalized = {
        id: item.stableId || `${groupName}:${slugify(category)}:${slugify(displayZh || item.en || String(index))}:${index}`,
        zh: displayZh,
        en: stripMarkdown(item.en),
        desc: stripMarkdown(item.desc),
        ...(item.mj && typeof item.mj === 'object' && !Array.isArray(item.mj)
          ? { mj: { ...item.mj } }
          : {}),
        ...(item.headAccessoryColorTarget
          ? { headAccessoryColorTarget: item.headAccessoryColorTarget }
          : {}),
        ...(item.eyewearColorTarget
          ? { eyewearColorTarget: item.eyewearColorTarget }
          : {}),
        ...(item.eyewearPlacementMode
          ? { eyewearPlacementMode: item.eyewearPlacementMode }
          : {}),
        ...(item.lyingSurface && typeof item.lyingSurface === 'object'
          ? { lyingSurface: { ...item.lyingSurface } }
          : {}),
        legacyIds: item.stableId && Array.isArray(item.legacyIds)
          ? [...item.legacyIds]
          : Array.from(new Set([
          ...(Array.isArray(item.legacyIds) ? item.legacyIds : []),
          ...ambientLightLegacyIds,
          legacyId,
        ])),
      };

      const rawSourceMeta = item.meta && typeof item.meta === 'object' && !Array.isArray(item.meta)
        ? item.meta
        : {};
      const { semantic, ...sourceMeta } = rawSourceMeta;
      const hasSemantic = Object.hasOwn(rawSourceMeta, 'semantic');
      if (hasSemantic && (!semantic || typeof semantic !== 'object' || Array.isArray(semantic))) {
        throw new TypeError(`Invalid catalog semantic object: ${normalized.id}`);
      }
      // Formal sources own semantics; legacy/custom libraries retain text inference.
      const inferredMeta = hasSemantic ? semantic : inferMeta(category, normalized);
      const sourceTags = Array.isArray(sourceMeta.tags) ? sourceMeta.tags : [];
      const inferredTags = Array.isArray(inferredMeta.tags) ? inferredMeta.tags : [];
      const subjectLight = groupName === 'camera' && category === LIGHT_STYLE_CATEGORY
        && item.subjectLight && typeof item.subjectLight === 'object' && !Array.isArray(item.subjectLight)
        ? item.subjectLight : null;
      const subjectLightTags = Array.isArray(subjectLight?.tags) ? subjectLight.tags : [];

      return {
        ...normalized,
        ...(captureInference ? { inferredMeta: structuredClone(inferredMeta) } : {}),
        meta: {
          ...inferredMeta,
          ...sourceMeta,
          ...(item.outerwear ? { outerwear: item.outerwear } : {}),
          ...(item.bottomWaist ? { bottomWaist: item.bottomWaist } : {}),
          ...(item.topUnderbust ? { topUnderbust: item.topUnderbust } : {}),
          ...(item.wearableColorTarget ? { wearableColorTarget: item.wearableColorTarget } : {}),
          ...(item.outerwearFit ? { outerwearFit: item.outerwearFit } : {}),
          ...(item.outerwearStyling ? { outerwearStyling: item.outerwearStyling, randomEligible: item.randomEligible } : {}),
          ...(item.outerwearFastenerRequirement !== undefined ? { outerwearFastenerRequirement: item.outerwearFastenerRequirement } : {}),
          ...(item.legacyPromptAliases ? { legacyPromptAliases: item.legacyPromptAliases } : {}),
          ...(item.legacyLabels ? { legacyLabels: item.legacyLabels } : {}),
          ...(subjectLight ? { subjectLight } : {}),
          tags: withTags([...inferredTags, ...sourceTags, ...subjectLightTags]),
        },
      };
    });
    return acc;
  }, {});
}

function cloneDatabase(rawDatabase) {
  return JSON.parse(JSON.stringify(rawDatabase));
}

function mergeCustomLibrary(customLibrary = []) {
  if (customLibrary && !Array.isArray(customLibrary) && typeof customLibrary === 'object') {
    return cloneDatabase(customLibrary);
  }

  const merged = cloneDatabase(database);

  customLibrary.forEach((entry) => {
    const group = entry.group;
    const category = stripMarkdown(entry.category);

    if (!group || !merged[group] || !category) return;

    if (!Array.isArray(merged[group][category])) {
      merged[group][category] = [];
    }

    merged[group][category].push({
      zh: stripMarkdown(entry.zh),
      en: stripMarkdown(entry.en),
      desc: stripMarkdown(entry.desc),
    });
  });

  return merged;
}

function buildCatalog(customLibrary = [], captureEntries = null) {
  const mergedDatabase = mergeCustomLibrary(customLibrary);

  const catalog = {
    regional: buildEntries('regional', mergedDatabase.Regional || {}, inferStyleMeta, Boolean(captureEntries)),
    wardrobe: buildEntries('wardrobe', mergedDatabase.Wardrobe || {}, inferWardrobeMeta, Boolean(captureEntries)),
    camera: buildEntries('camera', mergedDatabase.CameraLighting || {}, inferCameraMeta, Boolean(captureEntries)),
    locations: buildEntries('locations', mergedDatabase.Locations || {}, inferLocationMeta, Boolean(captureEntries)),
    character: buildEntries('character', mergedDatabase.Character || {}, inferCharacterMeta, Boolean(captureEntries)),
    negative: buildEntries('negative', mergedDatabase.Negative || {}, inferNegativeMeta, Boolean(captureEntries)),
  };
  if (captureEntries) {
    // Snapshot before aliases mutate entries and accessory categories move them.
    captureEntries(structuredClone(catalog));
    for (const categories of Object.values(catalog)) {
      for (const items of Object.values(categories)) {
        for (const item of items) delete item.inferredMeta;
      }
    }
  }
  applyRegionalLegacyOptionIds(catalog);
  applyWardrobeLegacyOptionIds(catalog);
  applyWardrobeLegacyPromptAliases(catalog);
  splitAccessoryCatalog(catalog.wardrobe);
  applyLocationLegacyPromptAliases(catalog);
  applyCharacterIdentityLegacyOptionIds(catalog);
  applyCharacterExpressionPoseLegacyOptionIds(catalog);
  applyCameraLegacyOptionIds(catalog);

  const flatten = (group) => Object.values(group).flat();

  return {
    catalog,
    flatCatalog: {
      regional: [STYLE_NONE_OPTION, ...flatten(catalog.regional)],
      locations: flatten(catalog.locations),
      framing: getByKey(catalog.camera, CAMERA_FRAMING_CATEGORY),
      angle: getByKey(catalog.camera, '相機視角 (Angle)'),
      orbit: getByKey(catalog.camera, '拍攝方位 (Orbit Angle)'),
      lens: getByKey(catalog.camera, FOCAL_LENGTH_CATEGORY),
      aperture: getByKey(catalog.camera, APERTURE_CATEGORY),
      shutter: getByKey(catalog.camera, SHUTTER_CATEGORY),
      lighting: getByKeys(catalog.camera, ENVIRONMENT_LIGHT_CATEGORIES),
      lightDirection: getByKey(catalog.camera, LIGHT_STYLE_CATEGORY),
      film: buildImagingSimulationOptions(getByKey(catalog.camera, CAMERA_FILM_CATEGORY)),
      effects: getByKey(catalog.camera, OPTICAL_EFFECTS_CATEGORY).length > 0 ? getByKey(catalog.camera, OPTICAL_EFFECTS_CATEGORY) : getByKey(catalog.camera, '特殊效果 (Special Effects)'),
      specialOutfits: getByKey(catalog.wardrobe, '特殊穿搭 (Special Outfits)'),
      outfitPresets: [
        OUTFIT_PRESET_NONE_OPTION,
        ...getByKey(catalog.wardrobe, '套裝 (Outfit Presets)'),
        ...getByKey(catalog.wardrobe, '連身 (Dresses)').filter((item) => !isNoneLikeItem(item)),
      ],
    },
    mergedDatabase,
  };
}

// Test/tool-only: deliberately bypass the shared runtime cache.
export function getCompiledCatalogForTesting(sourceDatabase) {
  if (sourceDatabase !== undefined && (!sourceDatabase || typeof sourceDatabase !== 'object' || Array.isArray(sourceDatabase))) {
    throw new TypeError('Expected a database object');
  }
  let entries;
  const { catalog } = buildCatalog(sourceDatabase ?? [], snapshot => { entries = snapshot; });
  return { entries, catalog };
}

function compileEngineRuntime(customLibrary = []) {
  const catalogRuntime = buildCatalog(customLibrary);
  return deepFreezeRuntime({
    ...catalogRuntime,
    controls: buildLockControls(catalogRuntime),
  });
}

const getEngineRuntime = createEngineRuntimeResolver(compileEngineRuntime);

export function getKnowledgeBaseOptions(customLibrary = []) {
  const { mergedDatabase } = getEngineRuntime(customLibrary);

  return CUSTOM_GROUP_OPTIONS.map((groupOption) => ({
    ...groupOption,
    categories: Object.keys(mergedDatabase[groupOption.value] || {}).sort(),
  }));
}

export function getKnowledgeBaseSnapshot(customLibrary = []) {
  const { mergedDatabase } = getEngineRuntime(customLibrary);
  return cloneDatabase(mergedDatabase);
}

export function createEmptyLocks() {
  return Object.fromEntries(
    LOCK_DEFINITIONS.map((definition) => [definition.key, definition.defaultValue ?? (definition.multi ? [] : '')])
  );
}

function getControlOptionByZh(controls, key, zh) {
  return controls.find((control) => control.key === key)?.options?.find((option) => option.zh === zh) || null;
}

function getControlOptionById(controls, key, id) {
  if (!id) return null;
  return controls.find((control) => control.key === key)?.options?.find((option) => option.id === id) || null;
}

function setControlOptionByZhIfInactive(normalizedLocks, controls, key, zh) {
  const option = getControlOptionByZh(controls, key, zh);
  if (!option) return;

  const current = getControlOptionById(controls, key, normalizedLocks[key]);
  if (!normalizedLocks[key] || isNoneLikeItem(current)) {
    normalizedLocks[key] = option.id;
  }
}

function setControlToNone(normalizedLocks, controls, key) {
  const noneOption = getControlOptionByZh(controls, key, '全無');
  normalizedLocks[key] = noneOption?.id || '';
}

const LEGACY_HAIR_STYLING_STATE_MIGRATIONS = legacyMappings.tables.LEGACY_HAIR_STYLING_STATE_MIGRATIONS.source;

function applyLegacyHairStylingStateMigration(normalizedLocks, rawLocks, controls) {
  const legacyStyleIds = new Map(
    LEGACY_HAIR_STYLING_STATE_MIGRATIONS.flatMap((entry) => entry.legacy.map(([label, index]) => [
      `character:${slugify('髮型 (Hairstyle)')}:${slugify(label)}:${index}`,
      entry.stateZh,
    ])),
  );
  const apply = (styleKey, stateKey) => {
    if (Object.prototype.hasOwnProperty.call(rawLocks || {}, stateKey)
      && rawLocks[stateKey] !== HAIR_STYLING_STATE_DEFAULT_ID) return;
    const stateZh = legacyStyleIds.get(rawLocks?.[styleKey]);
    if (!stateZh) return;
    const state = getControlOptionByZh(controls, stateKey, stateZh);
    if (state) normalizedLocks[stateKey] = state.id;
  };

  apply('hairstyleId', 'hairStylingStateId');
  apply('hairstyleAId', 'hairStylingStateAId');
  apply('hairstyleBId', 'hairStylingStateBId');
}

