const ACCESSORY_DEDUPE_CATEGORIES = new Set([
  '頭部配件 (Head Accessories)', '耳環 (Earrings)', '頸部 (Neck Accessories)', '腰部配件 (Waist Accessories)', '襪類 (Legwear)', '鞋款 (Shoes)',
]);

/** The accessory's own name ("lace ribbon choker" from "lace ribbon choker detail, subtle … accent"). */
function accessoryCorePhrase(item) {
  if (!item || isNoneLikeItem(item)) return '';
  const lead = String(item.en || '').split(',')[0].trim().toLowerCase().replace(/\s+(?:detail|accent|styling)$/, '');
  return lead.split(/\s+/).length >= 2 ? lead : '';
}

function buildTopColoredPrompt(topItem, color = null, { pattern = null, fit = null, styling = null } = {}) {
  if (!topItem || isNoneLikeItem(topItem)) return '';
  const base = normalizeWardrobePromptText(topItem.en);
  if (!base) return '';

  const fitText = fit && !isNoneLikeItem(fit) ? normalizeWardrobePromptText(fit.en) : '';
  const stylingText = styling && !isNoneLikeItem(styling) ? normalizeWardrobePromptText(styling.en) : '';
  const patternText = pattern && !isNoneLikeItem(pattern) ? normalizeWardrobePromptText(pattern.en) : '';
  const coloredBase = composeItemWearableColorPrompt(topItem, base, color);

  // Wardrobe order v1 (Cooper 2026-10-23): the garment name leads, its fit, styling and pattern follow.
  if (legacyWardrobeModifierOrder) {
    if (isHemOverlapStyling(styling)) return [fitText, coloredBase, patternText, stylingText].filter(Boolean).join(', ');
    return [fitText, stylingText, coloredBase, patternText].filter(Boolean).join(', ');
  }
  if (isHemOverlapStyling(styling)) {
    return [coloredBase, fitText, patternText, stylingText].filter(Boolean).join(', ');
  }
  return [coloredBase, fitText, stylingText, patternText].filter(Boolean).join(', ');
}

function getOuterwearFastenerTypes(outerwearItem) {
  if (!outerwearItem || isNoneLikeItem(outerwearItem)) return new Set();
  const authored = outerwearFasteners(outerwearItem);
  if (authored) return new Set(authored);
  const haystack = toHaystack(outerwearItem.zh, outerwearItem.en, outerwearItem.desc);
  const fasteners = new Set();
  if (hasAny(haystack, ['zip-front', 'zip-up', 'zipper', '拉鍊'])) fasteners.add('zip');
  if (hasAny(haystack, ['button-front', 'button-up', 'buttons', 'button closure', '扣子', '鈕扣'])) fasteners.add('button');
  return fasteners;
}

function getOuterwearOpeningFastenerRequirement(opening) {
  if (!opening || isNoneLikeItem(opening)) return '';
  if (opening.meta?.outerwearFastenerRequirement !== undefined) return opening.meta.outerwearFastenerRequirement;
  const haystack = toHaystack(opening.zh, opening.en, opening.desc);
  if (hasAny(haystack, ['zip-front', 'unzipped', '拉鍊'])) return 'zip';
  if (hasAny(haystack, ['button-front', 'unbuttoned', '扣子', '鈕扣'])) return 'button';
  return '';
}

function outerwearSupportsOpening(outerwearItem, opening) {
  if (isFullyClosedOpening(opening)) return true;
  const requiredFastener = getOuterwearOpeningFastenerRequirement(opening);
  if (!requiredFastener) return true;
  return getOuterwearFastenerTypes(outerwearItem).has(requiredFastener);
}

function buildOuterwearColoredPrompt(outerwearItem, color = null, { fit = null, pattern = null, opening = null, styling = null, minimalStyling = false } = {}) {
  if (!outerwearItem || isNoneLikeItem(outerwearItem)) return '';
  const resolvedBase = resolveOuterwearBase(outerwearItem, isNoneLikeItem(fit) ? null : fit);
  const base = normalizeWardrobePromptText(resolvedBase ?? outerwearItem.en);
  if (!base) return '';

  const isSimpleOversizeFit = resolvedBase === null && fit?.zh === 'Oversize';
  const fitText = resolvedBase === null && fit && !isNoneLikeItem(fit) && !isSimpleOversizeFit
    ? normalizeWardrobePromptText(fit.en)
    : '';
  const stylingText = isFullyClosedOpening(opening) && !outerwearStylingAllowsClosed(styling) ? '' : buildOuterwearStylingLeadText(styling, { minimal: minimalStyling });
  const patternText = pattern && !isNoneLikeItem(pattern) ? normalizeWardrobePromptText(pattern.en) : '';
  const openingText = isFullyClosedOpening(opening) ? fullyClosedOuterwearText(outerwearItem)
    : opening && !isNoneLikeItem(opening) ? normalizeWardrobePromptText(opening.en) : '';
  const coloredBase = outerwearItem.meta?.outerwear?.colorTargetsBody && color && !isNoneLikeItem(color)
    ? `${base}, body panels in ${color.en}`
    : composeWearableColorPrompt(base, color);
  const styledBase = isSimpleOversizeFit ? `oversized ${coloredBase}` : coloredBase;

  return [fitText, styledBase, patternText, openingText, stylingText].filter(Boolean).join(', ');
}

