function getAspectRatioOption(id, random = Math.random, exclusions = EMPTY_PREVIEW_REROLL_EXCLUSIONS) {
  const option = ASPECT_RATIO_OPTIONS.find((entry) => entry.id === id);
  if (option?.random) {
    return sample(exclusions.filterCandidates(ASPECT_RATIO_POOL, ['aspectRatio']), random);
  }
  return option || DEFAULT_ASPECT_RATIO;
}

function getDuoExpressionOption(id) {
  return DUO_EXPRESSION_OPTIONS.find((option) => option.id === id) || null;
}

function getPoseComposerOption(options, id) {
  return id ? options.find((option) => option.id === id) || null : null;
}

function isActivePoseComposerOption(option) {
  return Boolean(option && !isNoneLikeItem(option));
}

function resolvePoseComposerOption(options, id, predicate = () => true, exclusions = EMPTY_PREVIEW_REROLL_EXCLUSIONS, exclusionKeys = [], random = Math.random) {
  const option = getPoseComposerOption(options, id);
  if (!isActivePoseComposerOption(option)) return null;

  const candidates = options.filter((item) => (
    isActivePoseComposerOption(item)
    && !isRandomOption(item)
    && !isModelNaturalPoseComposerOption(item)
    && item.meta?.randomEligible !== false
    && predicate(item)
  ));
  if (isRandomOption(option)) return sample(exclusions.filterCandidates(candidates, exclusionKeys), random);
  return predicate(option) ? option : null;
}

const POSE_ANCHOR_RANDOM_NONE_RATE = 1 / 3;

function sampleWeightedPoseAnchor(candidates, normalizedRoll) {
  if (candidates.length === 0) return null;
  const weightedCandidates = candidates.map((candidate) => ({
    candidate,
    weight: Number.isFinite(candidate.meta?.randomWeight) && candidate.meta.randomWeight > 0
      ? candidate.meta.randomWeight
      : 1,
  }));
  const totalWeight = weightedCandidates.reduce((total, entry) => total + entry.weight, 0);
  let targetWeight = normalizedRoll * totalWeight;

  for (const entry of weightedCandidates) {
    if (targetWeight < entry.weight) return entry.candidate;
    targetWeight -= entry.weight;
  }
  return weightedCandidates.at(-1)?.candidate || null;
}

function resolvePoseComposerAnchorOption(id, predicate, exclusions, random = Math.random) {
  const option = getPoseComposerOption(POSE_COMPOSER_ANCHOR_OPTIONS, id);
  if (!isActivePoseComposerOption(option)) return null;
  if (!isRandomOption(option)) return predicate(option) ? option : null;

  const candidates = POSE_COMPOSER_ANCHOR_OPTIONS.filter((item) => (
    isActivePoseComposerOption(item)
    && !isRandomOption(item)
    && !isModelNaturalPoseComposerOption(item)
    && item.meta?.randomEligible !== false
    && predicate(item)
  ));
  const filteredCandidates = exclusions.filterCandidates(candidates, ['poseAnchorId']);
  const roll = random();
  if (filteredCandidates.length === 0) return null;
  if (roll < POSE_ANCHOR_RANDOM_NONE_RATE) return null;
  const concreteRoll = (roll - POSE_ANCHOR_RANDOM_NONE_RATE) / (1 - POSE_ANCHOR_RANDOM_NONE_RATE);
  return sampleWeightedPoseAnchor(filteredCandidates, concreteRoll);
}

function poseComposerOptionMatchesBase(option, baseId) {
  if (!option) return false;
  if (option.base) return option.base === baseId;
  if (Array.isArray(option.bases)) return option.bases.includes(baseId);
  return false;
}

function getWaterPoseBody(location) {
  const sceneType = getWaterPoseSceneType(location);
  if (sceneType === 'pool') return 'clear pool water';
  if (sceneType === 'cove') return 'clear shallow cove water';
  if (sceneType === 'beach') return 'clear shallow seawater';
  return 'clear shallow water';
}

function getWaterPoseEdge(location) {
  const sceneType = getWaterPoseSceneType(location);
  if (sceneType === 'pool') return 'tiled pool edge';
  if (sceneType === 'cove') return 'wet rock ledge at the cove shoreline';
  if (sceneType === 'beach') return 'wet sand shoreline at the waterline';
  return 'scene-appropriate water edge';
}

function getWaterImmersedAnchorPhrase(base, location, orientation = null) {
  const waterBody = getWaterPoseBody(location);
  const immersionDetail = 'with the whole lower body submerged and only the upper body above the water surface';
  const lyingOrientation = orientation?.id === 'lying-prone'
    ? `in ${waterBody}, floating face down`
    : orientation?.id === 'lying-side'
      ? `in ${waterBody}, floating on one side`
      : `in ${waterBody}, floating on the back`;
  const phrases = {
    standing: `standing waist-deep in ${waterBody} ${immersionDetail}`,
    sitting: `sitting low in ${waterBody} ${immersionDetail}`,
    kneeling: `kneeling in ${waterBody} ${immersionDetail}`,
    squatting: `squatting low in ${waterBody} ${immersionDetail}`,
    lying: orientation?.id
      ? `${lyingOrientation} with the body supported by the water surface ${immersionDetail}`
      : `floating or half-floating on the ${waterBody} surface ${immersionDetail}`,
  };
  return phrases[base?.id] || `in ${waterBody} ${immersionDetail}`;
}

function getWaterEdgeSupportAnchorPhrase(base, location, orientation = null) {
  const waterEdge = getWaterPoseEdge(location);
  const immersionDetail = 'with the whole lower body submerged and only the upper body above the water surface';
  const lyingOrientation = orientation?.id === 'lying-prone'
    ? 'lying face down at'
    : orientation?.id === 'lying-side'
      ? 'lying on one side at'
      : 'lying on the back at';
  const phrases = {
    standing: `standing in shallow water beside the ${waterEdge} ${immersionDetail} and forearms or hands supported on that edge`,
    sitting: `sitting at the ${waterEdge} ${immersionDetail} and hands or forearms supported on that edge`,
    kneeling: `kneeling at the ${waterEdge} ${immersionDetail} and forearms or hands supported on that edge`,
    squatting: `squatting low at the ${waterEdge} ${immersionDetail} and one or both hands supported on that edge`,
    lying: orientation?.id
      ? `${lyingOrientation} the ${waterEdge}, with the body partly supported by that edge ${immersionDetail}`
      : `half-reclining at the ${waterEdge} ${immersionDetail} and forearms supported on that edge`,
  };
  return phrases[base?.id] || `supported at the ${waterEdge} ${immersionDetail}`;
}

function getPoseComposerAnchorPhrase(anchor, base, location, orientation = null) {
  if (!anchor || !base) return '';
  if (anchor.meta?.supineSurfaceLed && orientation?.id === 'lying-supine') {
    const supineSurfacePhrase = anchor.meta.supineSurfacePhraseByOrientation?.[orientation.id]
      || anchor.phraseByOrientation?.[orientation.id];
    if (supineSurfacePhrase) return supineSurfacePhrase;
  }
  if (anchor.id === 'water-immersed') return getWaterImmersedAnchorPhrase(base, location, orientation);
  if (anchor.id === 'water-edge-support') return getWaterEdgeSupportAnchorPhrase(base, location, orientation);
  if (anchor.phraseByOrientation?.[orientation?.id]) return anchor.phraseByOrientation[orientation.id];
  return anchor.phraseByBase?.[base.id] || anchor.en || '';
}

function getPoseComposerBasePhrase(base) {
  const phrases = {
    standing: 'standing pose',
    sitting: 'sitting pose',
    kneeling: 'kneeling pose',
    squatting: 'squatting pose',
    lying: 'lying pose',
  };
  return phrases[base?.id] || base?.en || '';
}

function getPoseComposerAnchorEffect(anchor, base) {
  if (!anchor || !base) return '';

  if (anchor.id === 'water-immersed' || anchor.id === 'water-edge-support') {
    return 'water-contact realism with the whole lower body submerged and only the upper body above the water surface, visible waterline across the body, natural ripples around the torso and limbs, wet skin and damp fabric edges, clothing remains complete and non-transparent';
  }

  if (anchor.id !== 'shared-bathtub') return '';

  const waterContactEffects = {
    sitting: 'water-contact realism on the lower body and garment edges where they meet the bath water, clothing remains complete and non-transparent, visible water sheen and droplets, darker damp fabric tones, heavier wet folds',
    squatting: 'the outfit and exposed skin are soaked by bath water, clothing remains complete and non-transparent, visible water sheen and droplets, darker damp fabric tones, heavier wet folds',
    lying: 'the outfit and exposed skin are soaked by bath water, clothing remains complete and non-transparent, visible water sheen and droplets, darker damp fabric tones, heavier wet folds',
  };

  return waterContactEffects[base.id] || '';
}

function isModelNaturalPoseComposerOption(option) {
  return Boolean(
    option?.id?.startsWith('model-natural-')
    || option?.meta?.tags?.includes('any')
  );
}

function normalizePoseComposerArrangementPhrase(arrangement) {
  return stripTerminalPromptPunctuation(arrangement?.en || '')
    .replace(/\barrangement\b/gi, 'pose')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizePoseComposerOrientationPhrase(orientation) {
  return stripTerminalPromptPunctuation(orientation?.en || '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizePoseComposerLyingVariationPhrase(arrangement) {
  const text = normalizePoseComposerArrangementPhrase(arrangement);
  return text.replace(/^lying\s+pose(?:\s+with|\s*,)?\s*/i, '').trim();
}

function normalizePoseComposerHeadPhrase(head) {
  const text = stripTerminalPromptPunctuation(head?.en || '');
  if (!text) return '';
  if (/^(?:head|chin)\b/i.test(text)) return `her ${text}`;
  return text;
}

function normalizePoseComposerHandPhrase(handPose) {
  const text = stripTerminalPromptPunctuation(handPose?.en || '');
  if (!text) return '';
  if (/^front-camera\b/i.test(text)) return `a ${text}`;
  return text;
}

function normalizeSupineBodyPhrase(arrangement) {
  const text = stripTerminalPromptPunctuation(arrangement?.en || '')
    .replace(/\s+/g, ' ')
    .trim();
  if (!text) return '';
  if (/^her\s+/i.test(text)) return text;
  if (/^(?:body|torso|upper body|both knees|both legs|legs)\b/i.test(text)) return `her ${text}`;
  return text;
}

function getSupineSurfaceEnvironmentPhrase(anchor, orientation) {
  if (!anchor?.meta?.supineSurfaceLed || orientation?.id !== 'lying-supine') return '';
  const environment = anchor.meta.supineEnvironmentByOrientation?.[orientation.id];
  return stripTerminalPromptPunctuation(environment || '');
}

function buildSupinePoseComposerSentence({ arrangement, handPose, anchor, head, orientation }) {
  const surfacePhrase = anchor
    ? stripTerminalPromptPunctuation(
      getPoseComposerAnchorPhrase(anchor, { id: 'lying' }, null, orientation),
    )
    : '';

  const bodyPhrase = arrangement && !isModelNaturalPoseComposerOption(arrangement)
    ? normalizeSupineBodyPhrase(arrangement)
    : '';
  const handPhrase = handPose && !isModelNaturalPoseComposerOption(handPose)
    ? normalizePoseComposerHandPhrase(handPose)
    : '';
  const headPhrase = head && !isModelNaturalPoseComposerOption(head)
    ? normalizePoseComposerHeadPhrase(head)
    : '';
  const actionParts = [bodyPhrase ? `with ${bodyPhrase}` : '', handPhrase, headPhrase].filter(Boolean);
  const surfaceLedOpening = /^floating\b/i.test(surfacePhrase)
    ? `She is ${surfacePhrase}`
    : `She lies ${surfacePhrase}`;
  const poseSentence = surfacePhrase
    ? `${surfaceLedOpening}${actionParts.length > 0 ? `, ${actionParts.join(', ')}` : ''}.`
    : `She lies naturally${actionParts.length > 0 ? `, ${actionParts.join(', ')}` : ''}.`;
  const environmentPhrase = getSupineSurfaceEnvironmentPhrase(anchor, orientation);
  const anchorEffect = anchor?.id === 'water-edge-support'
    ? getPoseComposerAnchorEffect(anchor, { id: 'lying' })
    : '';

  return [poseSentence, environmentPhrase ? `${environmentPhrase}.` : '', anchorEffect ? `${anchorEffect}.` : '']
    .filter(Boolean)
    .join(' ');
}

function normalizePoseComposerPropPhrase(propAction) {
  return stripTerminalPromptPunctuation(propAction?.en || '');
}

/** "Her expression is delicate innocent expression, …" repeats the word, so a value that already
 * names an expression becomes "She has a delicate innocent expression, …" (Accessory v1, Nano). */
function nanoBananaExpressionSentence(value, lead) {
  if (!value) return '';
  if (legacyWardrobeModifierOrder || !/^[^,]*\bexpression\b\s*(?:,|$)/i.test(value)) return lead('Her expression is', value);
  return lead('She has', withIndefiniteArticle(value));
}

function withIndefiniteArticle(phrase) {
  const text = stripTerminalPromptPunctuation(phrase || '');
  if (!text || /^(?:a|an)\b/i.test(text)) return text;

  const consonantSoundException = /^(?:one(?:\b|-)|euro\b|ufo\b|uniform\b|unique\b|unit\b|university\b|use\b|user\b|usual\b)/i;
  const article = /^[aeiou]/i.test(text) && !consonantSoundException.test(text)
    ? 'an'
    : 'a';
  return `${article} ${text}`;
}

function buildPoseComposerResultPhrase({ base, orientation, arrangement, anchor, location }) {
  const orientationPhrase = orientation && !isModelNaturalPoseComposerOption(orientation)
    ? normalizePoseComposerOrientationPhrase(orientation)
    : '';
  const arrangementPhrase = arrangement && !isModelNaturalPoseComposerOption(arrangement)
    ? normalizePoseComposerArrangementPhrase(arrangement)
    : getPoseComposerBasePhrase(base);
  const isStructuredLyingPose = base?.id === 'lying' && orientationPhrase;
  const posePhrase = isStructuredLyingPose
    ? [orientationPhrase, arrangement && !isModelNaturalPoseComposerOption(arrangement)
      ? normalizePoseComposerLyingVariationPhrase(arrangement)
      : ''].filter(Boolean).join(' with ')
    : arrangementPhrase;
  const anchorPhrase = stripTerminalPromptPunctuation(getPoseComposerAnchorPhrase(anchor, base, location, orientation));

  if (!posePhrase) return anchorPhrase;
  if (!anchorPhrase) return posePhrase;

  const anchorTail = anchorPhrase
    .replace(/^(?:standing|sitting|kneeling|squatting|lying(?: down)?|reclining)\s+/i, '')
    .trim();
  if (anchorTail && anchorTail !== anchorPhrase) return `${posePhrase} ${anchorTail}`;
  if (/^(?:leaning|reclining|on|in|at|beside|by|against|near|with)\b/i.test(anchorPhrase)) {
    return `${posePhrase} ${anchorPhrase}`;
  }
  return `${posePhrase} with ${anchorPhrase}`;
}

function buildPoseComposerSentence({ base, orientation, arrangement, handPose, propAction, anchor, head, location }) {
  if (base?.id === 'lying' && orientation?.id === 'lying-supine') {
    return buildSupinePoseComposerSentence({ arrangement,
      handPose: isSelfiePoseHandOption(propAction) ? propAction : handPose,
      anchor, head, orientation });
  }

  const anchorEffect = getPoseComposerAnchorEffect(anchor, base);
  const naturalChoiceSelected = [arrangement, handPose, head].some(isModelNaturalPoseComposerOption);
  const headPhrase = head && !isModelNaturalPoseComposerOption(head)
    ? normalizePoseComposerHeadPhrase(head)
    : '';
  const handPhrase = handPose && !isModelNaturalPoseComposerOption(handPose)
    ? normalizePoseComposerHandPhrase(handPose)
    : '';
  const propPhrase = propAction
    ? normalizePoseComposerPropPhrase(propAction)
    : '';
  const poseResult = buildPoseComposerResultPhrase({ base, orientation, arrangement, anchor, location })
    || (naturalChoiceSelected ? 'natural posture' : '');
  const poseResultWithAnchorEffect = [poseResult, anchorEffect]
    .filter(Boolean)
    .join(', ');
  const posturePhrase = poseResultWithAnchorEffect
    ? (naturalChoiceSelected
      ? `a casual, relaxed, and natural ${poseResultWithAnchorEffect}`
      : withIndefiniteArticle(poseResultWithAnchorEffect))
    : '';
  const details = [headPhrase, propPhrase || handPhrase].filter(Boolean);

  if (!posturePhrase) {
    return details.length > 0 ? `She has ${details.join(', ')}.` : '';
  }

  if (details.length === 0) return `She presents ${posturePhrase}.`;
  return `She has ${details.join(', ')}, and presents ${posturePhrase}.`;
}

function buildPoseComposerItem(context) {
  if (context.subject.count !== 1) return null;

  const exclusions = context.previewRerollExclusions || EMPTY_PREVIEW_REROLL_EXCLUSIONS;
  const random = context.random || Math.random;
  const compatibilityContext = createPoseComposerCompatibilityContext({
    bucket: context.compositionVisibility?.bucket,
    angle: context.angle,
    orbit: context.orbit,
    wardrobeSignals: context.wardrobeSignals,
  });
  const requestedBase = getPoseComposerOption(POSE_COMPOSER_BASE_OPTIONS, context.locks?.poseBaseId);
  const requestedOrientation = getPoseComposerOption(POSE_COMPOSER_ORIENTATION_OPTIONS, context.locks?.poseOrientationId);
  const requestedArrangement = getPoseComposerOption(POSE_COMPOSER_ARRANGEMENT_OPTIONS, context.locks?.poseArrangementId);
  const requestedHand = getPoseComposerOption(POSE_COMPOSER_HAND_OPTIONS, context.locks?.poseHandId);
  const requestedProp = getPoseComposerOption(POSE_COMPOSER_PROP_OPTIONS, context.locks?.posePropId);
  const requestedAnchor = getPoseComposerOption(POSE_COMPOSER_ANCHOR_OPTIONS, context.locks?.poseAnchorId);
  // expression-pose-v2 P4: an active gaze supplies the head option; unused gaze
  // leaves older head locks in charge. An action that owns the head keeps it.
  const specifiedAction = getSpecifiedAction(context.locks);
  const gaze = context.rawLocks?.captureMode === 'observation' || specifiedAction?.ownsHead
    ? null : resolveGaze(context.locks?.gazeId, { orientationId: specifiedAction?.orientationId, orbit: context.orbit }, random);
  if (context.poseResolution) context.poseResolution.gaze = gaze;
  const headLockId = gaze ? gaze.headId || 'none' : context.locks?.poseHeadId;
  // Pose UI v2 part 2: 頭部 posture joins the gaze (or legacy head) in one head sentence.
  const posture = context.rawLocks?.captureMode === 'observation' || specifiedAction?.ownsHead
    ? null : resolveHeadPosture(context.locks?.headPostureId, gaze, random);
  if (context.poseResolution) context.poseResolution.posture = posture;
  // headPostureId appears only when a posture is in use, so older structured data keeps its shape.
  const headIds = head => ({ poseHeadId: head?.meta?.headPostureOnly ? 'none' : head?.id || 'none',
    ...(head?.meta?.headPostureId ? { headPostureId: head.meta.headPostureId } : {}) });

  const requestedHead = getPoseComposerOption(POSE_COMPOSER_HEAD_OPTIONS, headLockId);

  const resolveHead = (arrangementForHead = null, orientationForHead = null) => mergeHeadPosture(resolveHeadBase(arrangementForHead, orientationForHead), posture);
  const resolveHeadBase = (arrangementForHead = null, orientationForHead = null) => {
    // Compatibility constrains only the random pool. A concrete user lock is
    // intentional and must remain visible rather than being silently replaced.
    const predicate = isRandomOption(requestedHead)
      ? (option) => poseHeadSupportsOrbit(option, context.orbit)
        && poseComposerHeadSupportsRandomContext(option, {
          ...compatibilityContext,
          baseId: base?.id || null,
          orientationId: orientationForHead?.id || null,
          arrangement: arrangementForHead,
        })
      : () => true;
    return resolvePoseComposerOption(
      POSE_COMPOSER_HEAD_OPTIONS,
      headLockId,
      predicate,
      exclusions,
      ['poseHeadId'],
      random
    );
  };
  const base = resolvePoseComposerOption(
    POSE_COMPOSER_BASE_OPTIONS,
    context.locks?.poseBaseId,
    isRandomOption(requestedBase)
      ? (option) => poseComposerBaseSupportsRandomContext(option, compatibilityContext)
      : () => true,
    exclusions,
    ['poseBaseId'],
    random
  );

  if (specifiedAction) {
    const orientation = getPoseComposerOption(POSE_COMPOSER_ORIENTATION_OPTIONS, specifiedAction.orientationId);
    const head = resolveHead(null, orientation);
    const headText = isActivePoseComposerOption(head) ? `She has ${normalizePoseComposerHeadPhrase(head)}.` : '';
    const gesture = resolveGesture(context.locks?.gestureId, specifiedAction, { wardrobeSignals: context.wardrobeSignals, orbit: context.orbit }, random);
    if (context.poseResolution) context.poseResolution.gesture = gesture;
    const prop = resolveProp(context.locks?.propId, { wardrobeSignals: context.wardrobeSignals, orbit: context.orbit }, random);
    if (context.poseResolution) context.poseResolution.prop = prop;
    const actionText = actionTextWithGesture(specifiedAction, gesture, {}, prop);
    return {
      id: `character:姿勢組合器-pose-composer:${specifiedAction.id}:${head?.id || 'none'}`,
      zh: [specifiedAction.zh, head?.zh].filter(Boolean).join(' + '),
      en: [withLyingSurface(actionText.en, lyingSurfaceFor(specifiedAction, context.location)), headText].filter(Boolean).join(' '),
      desc: specifiedAction.descriptionZh,
      meta: {
        tags: ['pose_composer'], minVisibility: 'full',
        specifiedActionId: specifiedAction.id,
        supineGroundOnly: specifiedAction.meta?.supineGroundOnly === true,
        poseBaseId: specifiedAction.baseId, poseOrientationId: specifiedAction.orientationId,
        poseArrangementId: 'none', poseHandId: 'none', posePropId: 'none',
        ...headIds(head), poseAnchorId: 'none',
        gestureId: gesture?.id || 'none',
        ...(prop ? { propId: prop.id } : {}),
      },
    };
  }

  if (!base) {
    const handPose = resolvePoseComposerOption(
      POSE_COMPOSER_HAND_OPTIONS,
      context.locks?.poseHandId,
      isRandomOption(requestedHand)
        ? (option) => !(isFullyClosedOpening(context.locks?.outerwearOpeningId) && option.id === PULL_OPEN_HAND_ID)
          && poseComposerHandSupportsRandomContext(option, compatibilityContext)
        : () => true,
      exclusions,
      ['poseHandId'],
      random
    );
    const head = resolveHead();
    // The 道具 control (2026-10-22) runs here when no action is chosen; the retired prop lock still wins.
    const newProp = !context.locks?.posePropId || context.locks.posePropId === 'none'
      ? resolveProp(context.locks?.propId, { wardrobeSignals: context.wardrobeSignals, orbit: context.orbit }, random) : null;
    if (context.poseResolution) context.poseResolution.prop = newProp;
    const propAction = newProp || resolvePoseComposerOption(
      POSE_COMPOSER_PROP_OPTIONS,
      context.locks?.posePropId,
      isRandomOption(requestedProp)
        ? (option) => poseComposerPropSupportsRandomContext(option, compatibilityContext)
        : () => true,
      exclusions,
      ['posePropId'],
      random
    );
    const standaloneParts = [handPose, propAction, head].filter(isActivePoseComposerOption);
    if (standaloneParts.length === 0) return null;

    return {
      id: `character:姿勢組合器-pose-composer:${standaloneParts.map((part) => part.id).join(':')}`,
      zh: standaloneParts.map((part) => part.zh).join(' + '),
      en: buildPoseComposerSentence({ handPose, propAction, head, location: context.location }),
      desc: '由姿勢組合器生成的組合姿勢。',
      meta: {
        tags: ['pose_composer'],
        minVisibility: 'medium',
        poseBaseId: 'none',
        poseOrientationId: 'none',
        poseArrangementId: 'none',
        poseHandId: handPose?.id || 'none',
        posePropId: propAction?.id || 'none',
        ...headIds(head),
        poseAnchorId: 'none',
      },
    };
  }

  const matchesBase = (option) => poseComposerOptionMatchesBase(option, base.id);
  const orientation = base.id === 'lying'
    ? resolvePoseComposerOption(
      POSE_COMPOSER_ORIENTATION_OPTIONS,
      context.locks?.poseOrientationId,
      isRandomOption(requestedOrientation)
        ? matchesBase
        : (option) => option.id === requestedOrientation?.id && matchesBase(option),
      exclusions,
      ['poseOrientationId'],
      random
    )
    : null;
  const lyingCompatibilityContext = {
    ...compatibilityContext,
    orientationId: orientation?.id || null,
  };
  const arrangementCompatibility = (option) => poseComposerArrangementSupportsRandomContext(option, {
    ...lyingCompatibilityContext,
    requestedHead,
  });
  const matchesAnchor = (option) => (
    matchesBase(option)
    && (
      (
        base.id === 'lying'
        && orientation?.id === 'lying-supine'
        && option.meta?.supineSurfaceLed === true
      )
      || poseComposerAnchorAllowedByScene(
        option,
        context.location,
        context.locks?.locationId,
        context.sceneAttribute,
      )
    )
  );
  let arrangement = resolvePoseComposerOption(
    POSE_COMPOSER_ARRANGEMENT_OPTIONS,
    context.locks?.poseArrangementId,
    isRandomOption(requestedArrangement)
      ? (option) => matchesBase(option) && arrangementCompatibility(option)
      : matchesBase,
    exclusions,
    ['poseArrangementId'],
    random
  );
  const boundSupport = base.id === 'kneeling' && arrangement?.id === 'kneeling-all-fours'
    && (!isActivePoseComposerOption(requestedProp) || isRandomOption(requestedProp))
    && (!isActivePoseComposerOption(requestedHand) || isRandomOption(requestedHand)
      || isModelNaturalPoseComposerOption(requestedHand) || isKneelingSupportHand(requestedHand.id));
  const handPose = resolvePoseComposerOption(
    POSE_COMPOSER_HAND_OPTIONS,
    boundSupport && !isRandomOption(requestedHand) && !isKneelingSupportHand(requestedHand?.id)
      ? DEFAULT_KNEELING_SUPPORT_HAND_ID : context.locks?.poseHandId,
    isRandomOption(requestedHand)
      ? (option) => boundSupport
        ? isKneelingSupportHand(option.id)
        : !(isFullyClosedOpening(context.locks?.outerwearOpeningId) && option.id === PULL_OPEN_HAND_ID)
        && poseComposerHandSupportsRandomContext(option, {
        ...lyingCompatibilityContext,
        baseId: base.id,
        arrangement,
      })
      : () => true,
    exclusions,
    ['poseHandId'],
    random
  );
  arrangement = resolveKneelingSupportArrangement(arrangement, handPose?.id);
  const head = resolveHead(arrangement, orientation);
  const anchor = resolvePoseComposerAnchorOption(
    context.locks?.poseAnchorId,
    isRandomOption(requestedAnchor)
      ? (option) => matchesAnchor(option)
        && poseComposerOptionRandomEligibleForBase(option, base.id)
        && poseComposerOptionRandomEligibleForOrientation(option, orientation?.id)
      : matchesAnchor,
    exclusions,
    random,
  );
  const propAction = boundSupport ? null : resolvePoseComposerOption(
    POSE_COMPOSER_PROP_OPTIONS,
    context.locks?.posePropId,
    isRandomOption(requestedProp)
      ? (option) => poseComposerPropSupportsRandomContext(option, compatibilityContext)
      : () => true,
    exclusions,
    ['posePropId'],
    random
  );
  const parts = [base, orientation, arrangement, handPose, propAction, head, anchor].filter(Boolean);

  return {
    id: `character:姿勢組合器-pose-composer:${parts.map((part) => part.id).join(':')}`,
    zh: parts.map((part) => part.zh).join(' + '),
    en: buildPoseComposerSentence({ base, orientation, arrangement, handPose, propAction, anchor, head, location: context.location }),
    desc: '由姿勢組合器生成的組合姿勢。',
    meta: {
      tags: ['pose_composer'],
      minVisibility: 'full',
      poseBaseId: base.id,
      poseOrientationId: orientation?.id || 'none',
      poseArrangementId: arrangement?.id || 'none',
      poseHandId: handPose?.id || 'none',
      posePropId: propAction?.id || 'none',
      ...headIds(head),
      poseAnchorId: anchor?.id || 'none',
    },
  };
}

const CHEST_VISIBLE_HAND_IDS = new Set([
