const MEDIUM_HIDDEN_HAND_IDS = new Set([
  'hands-on-thighs',
  'one-hand-ground-one-leg',
  'one-hand-knee-one-down',
  'one-hand-ankle',
  'hands-gathered-lower-abdomen',
  'hands-palms-planted-ground',
  'hands-elbows-planted-ground',
