function buildAccessoryPrompt(item) {
  if (typeof item === 'string') return item.replace(/\s+/g, ' ').trim();
  if (!item || isNoneLikeItem(item)) return '';
  return stripMarkdown(item.en).replace(/\s+/g, ' ').trim();
}

const HEAD_ACCESSORY_COLOR_TERMS = [
  'mirror-chrome silver',
  'multicolored horizontal stripes',
  'dark grey',
  'light grey',
  'off-white',
  'dark brown',
  'light brown',
  'bright red',
  'neon red',
  'light blue',
  'dark blue',
  'royal blue',
  'neon blue',
  'light green',
  'dark green',
  'olive green',
  'neon green',
  'soft yellow',
  'neon yellow',
  'black',
  'white',
  'grey',
  'red',
  'pink',
  'silver',
  'gold',
].sort((left, right) => right.length - left.length);

function stripHeadAccessoryColorTerms(text) {
  let normalized = String(text || '');
  HEAD_ACCESSORY_COLOR_TERMS.forEach((term) => {
    normalized = normalized.replace(new RegExp(`\\b${escapeRegExpPattern(term)}\\b`, 'gi'), ' ');
  });
  return normalized
    .replace(/\s+/g, ' ')
    .replace(/\s+,/g, ',')
    .replace(/,\s*,+/g, ',')
    .replace(/^\s*,\s*|\s*,\s*$/g, '')
    .trim();
}

function buildTargetedHeadAccessoryColorPrompt(headAccessory, base, color) {
  const target = normalizeWardrobePromptText(headAccessory?.headAccessoryColorTarget);
  if (!target) return '';

  const targetPattern = new RegExp(escapeRegExpPattern(target), 'i');
  if (!targetPattern.test(base)) return '';

  const neutralTarget = stripHeadAccessoryColorTerms(target);
  if (!neutralTarget) return '';

  const coloredTarget = composeWearableColorPrompt(neutralTarget, color, { placement: 'inline' });
  return base.replace(targetPattern, coloredTarget);
}

function buildHeadAccessoryPrompt(headAccessory, color = null) {
  const base = buildAccessoryPrompt(headAccessory);
  if (!base || !color || isNoneLikeItem(color)) return base;

  const targetedColorPrompt = buildTargetedHeadAccessoryColorPrompt(headAccessory, base, color);
  if (targetedColorPrompt) return targetedColorPrompt;

  const neutralBase = stripHeadAccessoryColorTerms(base);
  return composeWearableColorPrompt(neutralBase, color, { placement: 'inline' });
}

function buildTargetedEyewearColorPrompt(eyewear, base, color) {
  const target = normalizeWardrobePromptText(eyewear?.eyewearColorTarget);
  if (!target || !color || isNoneLikeItem(color)) return '';

  const targetPattern = new RegExp(escapeRegExpPattern(target), 'i');
  if (!targetPattern.test(base)) return '';

  const neutralTarget = stripHeadAccessoryColorTerms(target);
  if (!neutralTarget) return '';

  const fabricColor = {
    ...color,
    en: normalizeWardrobePromptText(color.en).replace(/\s+frame$/i, ''),
  };
  const coloredTarget = composeWearableColorPrompt(neutralTarget, fabricColor, { placement: 'inline' });
  return base.replace(targetPattern, coloredTarget);
}

function buildEyewearPrompt(eyewear, color = null, placement = null) {
  if (!eyewear || isNoneLikeItem(eyewear)) return '';
  const base = buildAccessoryPrompt(eyewear);
  const colorText = color && !isNoneLikeItem(color) ? buildAccessoryPrompt(color) : '';
  const targetedColorPrompt = buildTargetedEyewearColorPrompt(eyewear, base, color);
  const baseText = targetedColorPrompt || (colorText ? [colorText, base].filter(Boolean).join(', ') : base);
  const placementText = eyewear.eyewearPlacementMode === 'fixed-face' || (placement && isNoneLikeItem(placement))
    ? ''
    : placement && !isNoneLikeItem(placement)
      ? buildAccessoryPrompt(placement)
      : 'worn normally on the face, lenses aligned over the eyes';

  return [baseText, placementText].filter(Boolean).join(', ');
}

function cleanSubjectAccessoryPrompt(item) {
  return buildAccessoryPrompt(item)
    .replace(/^wearing\s+/i, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function buildSubjectAccessoryPrompt({ eyewear, eyewearColor, eyewearPlacement, earrings, nosePiercing, lipPiercing, neckAccessory, headphones, faceCovering } = {}) {
  const parts = [
    buildEyewearPrompt(eyewear, eyewearColor, eyewearPlacement),
    cleanSubjectAccessoryPrompt(earrings),
    cleanSubjectAccessoryPrompt(headphones),
    cleanSubjectAccessoryPrompt(faceCovering),
    cleanSubjectAccessoryPrompt(nosePiercing),
    cleanSubjectAccessoryPrompt(lipPiercing),
    cleanSubjectAccessoryPrompt(neckAccessory),
  ].filter(Boolean);

  const dedupedParts = dedupeRepeatedCommaFragments(parts);
  return dedupedParts.length > 0 ? `with ${joinNaturalList(dedupedParts)}` : '';
}

const ACCESSORY_FILLER_CLAUSE = /^(?:a |an )?(?:subtle|understated)\b[^,]*\b(?:accent|styling|detail)$/i;
const DEFAULT_EYEWEAR_PLACEMENT_TEXT = 'worn normally on the face, lenses aligned over the eyes';

/** Accessory v1 (Cooper 2026-10-23): one list for a single subject's head, face and neck accessories,
 * item first (eyewear name before its colour, then its placement). `compact` is for Z-Image and Nano:
 * it drops filler clauses and the default "worn normally on the face" placement. GPT keeps every
 * selected description. */
function buildSingleSubjectAccessoryList(wardrobeSlots, wardrobeColors, { compact = false } = {}) {
  const clean = (text) => {
    if (!compact) return text;
    return String(text || '').replace(DEFAULT_EYEWEAR_PLACEMENT_TEXT, '').split(/\s*,\s*/).map((clause) => clause.trim())
      .filter((clause) => clause && !ACCESSORY_FILLER_CLAUSE.test(clause)).join(', ');
  };
  const eyewearBase = buildAccessoryPrompt(wardrobeSlots.eyewear);
  const eyewearItem = wardrobeSlots.eyewear && !isNoneLikeItem(wardrobeSlots.eyewear)
    ? (() => {
        const color = wardrobeSlots.eyewearColor;
        const targeted = buildTargetedEyewearColorPrompt(wardrobeSlots.eyewear, eyewearBase, color);
        const colorText = color && !isNoneLikeItem(color) ? buildAccessoryPrompt(color) : '';
        const placement = wardrobeSlots.eyewearPlacement;
        const placementText = wardrobeSlots.eyewear.eyewearPlacementMode === 'fixed-face' || (placement && isNoneLikeItem(placement))
          ? '' : placement && !isNoneLikeItem(placement) ? buildAccessoryPrompt(placement) : DEFAULT_EYEWEAR_PLACEMENT_TEXT;
        return [targeted || [eyewearBase, colorText].filter(Boolean).join(', '), placementText].filter(Boolean).join(', ');
      })()
    : '';
  const parts = [
    cleanSubjectAccessoryPrompt(buildHeadAccessoryPrompt(wardrobeSlots.headAccessory, wardrobeColors?.headAccessoryColor)),
    eyewearItem,
    cleanSubjectAccessoryPrompt(wardrobeSlots.earrings),
    cleanSubjectAccessoryPrompt(wardrobeSlots.headphones),
    cleanSubjectAccessoryPrompt(wardrobeSlots.faceCovering),
    cleanSubjectAccessoryPrompt(wardrobeSlots.nosePiercing),
    cleanSubjectAccessoryPrompt(wardrobeSlots.lipPiercing),
    cleanSubjectAccessoryPrompt(wardrobeSlots.neckAccessory),
  ].map(clean).filter(Boolean);
  const deduped = dedupeRepeatedCommaFragments(parts);
  // Items carry their own commas, so they are separated by semicolons to keep the boundaries readable.
  if (deduped.length <= 1) return deduped[0] || '';
  return `${deduped.slice(0, -1).join('; ')}; and ${deduped[deduped.length - 1]}`;
}

function appendSubjectAccessories(subjectText, accessoryText) {
  const cleanedSubject = stripMarkdown(subjectText || '').replace(/\s+/g, ' ').trim();
  if (!cleanedSubject) return accessoryText || '';
  if (!accessoryText) return cleanedSubject;
  const separator = /^woman\s+\d\b/i.test(accessoryText) ? ', ' : ' ';
  return `${cleanedSubject}${separator}${accessoryText}`;
}

function buildRoleSubjectAccessoryPrompt(wardrobeSlots, role) {
  const suffix = role === 'a' ? 'A' : 'B';
  const accessoryText = buildSubjectAccessoryPrompt({
    eyewear: wardrobeSlots[`eyewear${suffix}`],
    eyewearColor: wardrobeSlots[`eyewear${suffix}Color`],
    eyewearPlacement: wardrobeSlots[`eyewear${suffix}Placement`],
    headphones: wardrobeSlots[`headphones${suffix}`],
    faceCovering: wardrobeSlots[`faceCovering${suffix}`],
    earrings: wardrobeSlots[`earrings${suffix}`],
    neckAccessory: wardrobeSlots[`neckAccessory${suffix}`],
  });

  return accessoryText ? `woman ${role === 'a' ? '1' : '2'} ${accessoryText}` : '';
}

function buildFacialFeaturesPrompt(faceItem, { eyewear, earrings } = {}) {
  const baseFace = faceItem && !isNoneLikeItem(faceItem)
    ? stripMarkdown(faceItem.en).replace(/\s+/g, ' ').trim()
    : '';
  const normalizeFaceAccessory = (value) => value.replace(/^wearing\s+/i, '').trim();
  const faceAccessories = [buildAccessoryPrompt(eyewear), buildAccessoryPrompt(earrings)]
    .filter(Boolean)
    .map(normalizeFaceAccessory);
  const accessoryText = faceAccessories.length > 0 ? `wearing ${faceAccessories.join(' and ')}` : '';

  if (!baseFace && !accessoryText) return '';
  if (!baseFace) return accessoryText;
  if (!accessoryText) return baseFace;
  return `${baseFace}. ${accessoryText}`;
}

function ensureTerminalPeriod(value) {
  const cleaned = stripMarkdown(value).trim();
  if (!cleaned) return '';
  if (/[.!?]$/.test(cleaned)) return cleaned;
  return `${cleaned}.`;
}

