  const postureBase = stripTerminalPromptPunctuation(cleanPublicDuoPromptText(firstStructuredValue(valuesByLabel, ['Duo Pose Base'])));
  const angle = stripTerminalPromptPunctuation(firstStructuredValue(valuesByLabel, ['Angle']));
  const orbit = stripTerminalPromptPunctuation(firstStructuredValue(valuesByLabel, ['Orbit Angle']));
  const viewpoint = [angle, orbit].filter(Boolean).join(', ');
  const framingText = buildGptDuoFlexibleFramingText(context);

  return [
    scenario ? ensureTerminalPeriod(capitalizePromptLead(scenario)) : '',
    postureBase ? `Their body posture is ${ensureTerminalPeriod(postureBase)}` : '',
    !isNoneLikeItem(context.framing)
      ? `Use ${framingText}${viewpoint ? ` with ${viewpoint}` : ''} as a loose photographic guide, allowing natural crop, overlap, body blocking, and partial occlusion when it makes the moment feel candid and real.`
      : viewpoint ? ensureTerminalPeriod(viewpoint) : '',
  ].filter(Boolean).join(' ');
}

function protectNewLayeredHemSources(text) {
  const topHemSource = getTopStylingOption('hem-overlap')?.en;
  const coatHemSource = database.Wardrobe['外套穿法 (Outerwear Styling)'].find(item => item.outerwearStyling?.kind === 'hem-overlap')?.en;
  const sources = [];
  // Same words can describe distinct garment layers. Only the new pairing
  // protects whole instructions; all legacy deduplication remains unchanged.
  if (topHemSource && coatHemSource && text.includes(topHemSource)
    && (text.includes(`${coatHemSource},`) || text.includes(`${coatHemSource}.`) || text.endsWith(coatHemSource))) {
    for (const source of [topHemSource, coatHemSource]) text = text.replaceAll(source, () => {
      sources.push(source);
      return `VPSTUDIO_LAYER_SOURCE_${sources.length - 1}`;
    });
  }
  return { text, restore: value => value.replace(/VPSTUDIO_LAYER_SOURCE_(\d+)/g, (_, index) => sources[Number(index)]) };
}

function cleanGptSinglePromptText(value) {
  const normalized = stripMarkdown(value || '')
    .replace(/\s+/g, ' ')
    .replace(/\.\s*,/g, '.')
    .replace(/\s*,\s*,+/g, ', ')
    .replace(/\s+,/g, ',')
    .replace(/,\s*\./g, '.')
    .trim();
  const protectedSources = protectNewLayeredHemSources(normalized);
  return protectedSources.restore(dedupeExactPromptText(protectedSources.text));
}

