const FULL_BODY_CHARACTER_IMAGE_TYPE = 'Create a photorealistic character reference portrait in a single 9:16 vertical image';
const FULL_BODY_CHARACTER_LIGHTING = 'Clean even lighting with clear facial, body, fabric, and footwear readability';
const FULL_BODY_CHARACTER_CAMERA_LOOK = 'Full-body view of the subject standing naturally, centered vertical framing, complete figure visible from head to toe, both hands and both feet completely visible, comfortable space above the hair and below the shoes, natural body proportions, no crop, no hidden limbs, clean realistic character-reference photography, clear facial and garment detail, no visible text';

function renderFullBodyCharacterPrompt(promptModel) {
  const {
    valuesByLabel,
    context,
    wardrobe,
  } = promptModel;
  if (context.subject?.count !== 1) return '';

  const section = (title, value) => {
    const cleaned = ensureTerminalPeriod(cleanGptSinglePromptText(value || ''));
    return cleaned ? `${title}:\n${cleaned}` : '';
  };
  const blockSection = (title, value) => {
    const cleaned = String(value || '')
      .replace(/[`*]/g, '')
      .split('\n')
      .map((line) => line.replace(/\s+/g, ' ').trim())
      .join('\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
    return cleaned ? `${title}:\n${cleaned}` : '';
  };
  const {
    subjectText,
    wardrobeText,
    subjectLead,
    wardrobeLead,
  } = buildGptPromptSectionSources(valuesByLabel, context, { includeBodyType: true });
  const characterProfileSubjectBlock = isCharacterProfileSubject(context.subject)
    ? buildGptFullBodyCharacterProfileSubjectBlock(context.subject, context.locks, wardrobe)
    : '';
  const characterProfileGroups = isCharacterProfileSubject(context.subject)
    ? buildCharacterCardProfileGroups(context.subject, context.locks, wardrobe)
    : null;
  const specialOutfitText = firstStructuredValue(valuesByLabel, ['Special Outfit']);
  const specialOutfitGroups = specialOutfitText
    ? buildGptSingleSpecialOutfitGroups(
        specialOutfitText,
        getStructuredValues(valuesByLabel, ['Outerwear']),
        context
      )
    : { hairAndBodyText: '', wardrobeText: '' };
  let resolvedSubjectText = characterProfileSubjectBlock
    || buildGptSingleFullFidelityText(subjectText);
  if (specialOutfitGroups.hairAndBodyText) {
    const baseSubjectText = characterProfileSubjectBlock
      ? resolvedSubjectText
      : `${subjectLead} ${resolvedSubjectText}`.trim();
    resolvedSubjectText = [
      baseSubjectText,
      `Hair and body details:\n${specialOutfitGroups.hairAndBodyText}`,
    ].filter(Boolean).join('\n\n');
  }
  const specialOutfitWardrobeBlock = specialOutfitGroups.wardrobeText;
  const resolvedWardrobeText = specialOutfitWardrobeBlock
    || buildGptSingleFullFidelityWardrobeText(wardrobeText)
    || characterProfileGroups?.outfit
    || '';
  const fullBodyCameraLook = /\bCAUTION\b/.test(resolvedWardrobeText)
    ? FULL_BODY_CHARACTER_CAMERA_LOOK.replace(/, no visible text$/, '')
    : FULL_BODY_CHARACTER_CAMERA_LOOK;

  return [
    section('Image Type', FULL_BODY_CHARACTER_IMAGE_TYPE),
    resolvedSubjectText
      ? characterProfileSubjectBlock || specialOutfitGroups.hairAndBodyText
        ? blockSection('Subject', resolvedSubjectText)
        : section('Subject', `${subjectLead} ${resolvedSubjectText}`)
      : '',
    resolvedWardrobeText
      ? specialOutfitWardrobeBlock
        ? blockSection('Wardrobe', resolvedWardrobeText)
        : section('Wardrobe', `${wardrobeLead} ${resolvedWardrobeText}`)
      : '',
    section('Lighting', FULL_BODY_CHARACTER_LIGHTING),
    section('Camera Look', fullBodyCameraLook),
  ].filter(Boolean).join('\n\n');
}

function buildFixedFramingDerivedProjectedScene(sourceContext, derivedContext, preset) {
  if (sourceContext.observationCapture && preset.id === 'chest-up-portrait') return { mode: 'fullSource', locationText: captureChestScene(sourceContext.observationCapture), worldSceneText: '', sceneAccentText: '' };
  if (
    preset.fixedCompositionHandling === 'projectScene'
    && isFixedCompositionSetActive(sourceContext.fixedCompositionSet)
  ) {
    if (isCarriageFixedSet(sourceContext.fixedCompositionSet)) return Object.freeze({
      mode: 'compactSource', locationText: carriageSceneText(sourceContext.fixedCompositionSet,
        { compact: true, background: sourceContext.fixedSetBackgroundState }),
      worldSceneText: '', sceneAccentText: '',
    });
    if (isStationFixedSet(sourceContext.fixedCompositionSet)) return Object.freeze({
      mode: 'compactSource',
      locationText: stationSceneText(sourceContext.fixedCompositionSet, { compact: true }),
      worldSceneText: '', sceneAccentText: '',
    });
    const authoredScene = AI_FIXED_SET_SCENE_PHRASES[sourceContext.fixedCompositionSet.id]
      || cleanFixedSetOpeningSentence(sourceContext.fixedCompositionSet);
    const locationText = projectSceneSourceText(
      authoredScene.replace(/^The central scene is\s+/i, ''),
      'compactSource',
    );

    return Object.freeze({
      mode: 'compactSource',
      locationText,
      worldSceneText: '',
      sceneAccentText: '',
    });
  }

  // Re-project from resolved sources rather than inheriting a parent crop's
  // clause truncation. The matching renderer owns directional/compact wording.
  return buildProjectedScene(preset.preserveCaptureState ? {
    ...derivedContext,
    compositionVisibility: {
      ...derivedContext.compositionVisibility,
      scene: { ...derivedContext.compositionVisibility.scene, mode: 'fullSource' },
    },
  } : derivedContext);
}

function buildFixedFramingDerivedPromptModel({
  sourcePromptModel,
  sourceContext,
  preset,
  character,
  wardrobe,
  wardrobeColors,
  lightDirection,
  film,
}) {
  const baseDerivedContext = createFixedFramingDerivedContext(sourceContext, preset);
  wardrobe = projectUnderbustTopFit(projectClosedOuterwearWardrobe(projectOuterwearStyling(projectTopHemOverlap(projectAudioForFraming(wardrobe, baseDerivedContext), baseDerivedContext), getCompositionVisibilityProjection(baseDerivedContext))), getCompositionVisibilityProjection(baseDerivedContext));

  if (!preset.projectResolvedSources) {
    const projectedCharacter = projectBodyTypeCharacter(character, baseDerivedContext, wardrobe);
    return {
      ...sourcePromptModel,
      ...buildStructuredPromptSections(
        baseDerivedContext,
        projectedCharacter,
        wardrobe,
        wardrobeColors,
        lightDirection,
        film,
      ),
      context: baseDerivedContext,
      character: projectedCharacter,
      wardrobe,
      wardrobeColors,
    };
  }

  const compositionVisibility = baseDerivedContext.compositionVisibility;
  const poseComposer = extractCharacterSlots(character).poseComposer;
  const projectedCanonicalPoseText = buildProjectedCanonicalPoseText(baseDerivedContext, poseComposer);
  const derivedContext = {
    ...baseDerivedContext,
    ...(isStationFixedSet(sourceContext.fixedCompositionSet)
      ? { stationFixedSceneSource: sourceContext.fixedCompositionSet } : {}),
    ...(isCarriageFixedSet(sourceContext.fixedCompositionSet)
      ? { carriageFixedSceneSource: sourceContext.fixedCompositionSet } : {}),
    subject: isCharacterProfileSubject(baseDerivedContext.subject)
      ? projectCharacterProfileSubject(baseDerivedContext.subject, compositionVisibility)
      : baseDerivedContext.subject,
    projectedCanonicalPoseText,
    projectedScene: buildFixedFramingDerivedProjectedScene(sourceContext, baseDerivedContext, preset),
  };
  const projectedCharacter = projectBodyTypeCharacter(character, derivedContext, wardrobe);

  return {
    ...sourcePromptModel,
    ...buildStructuredPromptSections(
      derivedContext,
      projectedCharacter,
      wardrobe,
      wardrobeColors,
      lightDirection,
      film,
    ),
    context: derivedContext,
    character: projectedCharacter,
    wardrobe,
    wardrobeColors,
  };
}

