  return personFragments;
}

function compactAiGarmentValue(value, preferredRole = '', primarySource = '', wearSources = [], surfaceSource = '') {
  const sourceText = primarySource || value;
  if (isMinimalCoverageGarmentSource(sourceText)) {
    // Retain only authored clauses that survived the shared crop projection.
    // This preserves the defining cup/tie fit while respecting colors/patterns
    // and avoids recovering hidden lower-body details in chest derivatives.
    const visibleSource = splitAiSourceFragments(sourceText).filter(fragment => value.includes(fragment));
    const visibleWear = wearSources.filter(source => source && value.includes(source));
    const visibleSurface = splitAiSourceFragments(surfaceSource).filter(fragment => value.includes(fragment));
    return [...new Set([...visibleSource, ...visibleWear, ...visibleSurface])].join(', ');
  }
  if (/\bJapanese sailor school blouse\b|\bJapanese sailor-uniform pleated skirt\b/i.test(sourceText)) {
    const sourceFragments = splitAiSourceFragments(sourceText);
    const keep = preferredRole === 'top'
      ? /\b(?:sailor school blouse|relaxed straight-cut body|undersized close-fitting body|navy sailor collar|navy scarf tie|navy cuffs)\b/i
      : /\b(?:sailor-uniform pleated skirt|broad pressed pleats|above-knee hem|near-floor maxi hem)\b/i;
    return [...sourceFragments.filter((fragment) => keep.test(fragment)), ...wearSources.filter(source => source && value.includes(source))].join(', ');
  }
  if (
    preferredRole === 'waistAccessory'
    && /\b(?:butterfly waist chain|navel (?:piercing|ring))\b/i.test(sourceText)
  ) {
    return compactAiSelectedAccessoryText(sourceText, 'waistAccessory');
  }

  const fragments = splitAiSourceFragments(value);
  const roleFragments = fragments.filter((fragment) => classifyCompleteLookWardrobeFragment(fragment) === preferredRole);
  const primarySourceFragments = splitAiSourceFragments(primarySource);
  const selectedOuterwear = preferredRole === 'outerwear'
    ? primarySourceFragments.find((fragment) => /\b(?:shirt|jacket|coat|blazer|cardigan|hoodie|cape|cloak|robe|poncho)\b/i.test(fragment))
    : '';
  const selectedPrimary = selectedOuterwear || primarySourceFragments.find((fragment) => classifyCompleteLookWardrobeFragment(fragment) === preferredRole)
    || primarySourceFragments.find((fragment) => classifyCompleteLookWardrobeFragment(fragment))
    || primarySourceFragments[0]
    || '';
  const inferredPrimary = roleFragments.find((fragment) => /\b(?:shorts?|pants|skirts?|jeans|leggings|trousers|bottoms?|tops?|shirt|tee|camisole|jacket|coat|blazer|shoes?|boots?|heels?|pumps?|sandals?|sneakers?|loafers?)\b/i.test(fragment)
      && !/\b(?:waist|hem|fit|tucked|button|zipper|surface|pattern|texture|silhouette|line|cuffs?|sleeves?)\b/i.test(fragment))
    || roleFragments[0]
    || fragments.find((fragment) => classifyCompleteLookWardrobeFragment(fragment))
    || fragments[0]
    || '';
  const lowerCropBoundary = fragments.some((fragment) => /\bat the lower crop edge\b/i.test(fragment))
    && !/\bat the lower crop edge\b/i.test(selectedPrimary)
    ? ' at the lower crop edge'
    : '';
  const normalizedSelectedPrimary = selectedPrimary.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const normalizedInferredPrimary = inferredPrimary.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const inferredKeepsSelectedPrimary = normalizedSelectedPrimary
    && normalizedInferredPrimary
    && (
      normalizedInferredPrimary.includes(normalizedSelectedPrimary)
      || normalizedSelectedPrimary.includes(normalizedInferredPrimary)
    );
  const primary = selectedPrimary && !inferredKeepsSelectedPrimary
    ? `${selectedPrimary}${lowerCropBoundary}`
    : inferredPrimary;
  // Selected wear instructions are independent of decorative structure such as
  // a hem. Retain only instructions present in the shared projected source.
  const visibleWearSources = wearSources.filter((source) => source && value.includes(source));
  // Selected surface design is an independent visual anchor. Keep only its
  // clauses already present in the shared projected garment, never hidden raw text.
  const visibleSurfaceFragments = splitAiSourceFragments(surfaceSource).filter(fragment => fragments.includes(fragment));
  if (preferredRole === 'outerwear') {
    const visibleIdentity = primarySourceFragments.filter(fragment => fragments.includes(fragment));
    return [...new Set([primary, ...visibleIdentity, ...visibleWearSources, ...visibleSurfaceFragments].filter(Boolean))].join(', ');
  }
  const structuralDetail = fragments.find((fragment) => /\b(?:neckline|flare|pleated|ruffled|slit|hem|boning|lace trim|garter|cut-out|open shoulder|one shoulder line exposed|both shoulder lines exposed|draped off one shoulder|worn off both shoulders|upper back exposed|high-cut|wide-leg|straight-leg)\b/i.test(fragment) && fragment !== primary
    && !visibleSurfaceFragments.includes(fragment)
    && !visibleWearSources.some((source) => source.includes(fragment))) || '';
  const hasSelectedGarterBelt = fragments.some((fragment) => /\bseparate lace garter belt worn over the bottoms at the hips\b/i.test(fragment));
  const selectedGarterStrapConnection = hasSelectedGarterBelt
    ? fragments.find((fragment) => /\bslim straps connecting to the stocking tops\b/i.test(fragment)) || ''
    : '';
  return [...new Set([primary, structuralDetail, selectedGarterStrapConnection, ...visibleWearSources, ...visibleSurfaceFragments].filter(Boolean))].join(', ');
}

function isAdhesiveTapeWrapOutfitPresetSource(value) {
  const text = stripMarkdown(value || '').replace(/\s+/g, ' ').trim();
  return /\bbody-wrapping construction\b/i.test(text)
    && /\bseparate independent groups of\b/i.test(text)
    && /\badhesive tape\b/i.test(text);
}

function extractAdhesiveTapeWrapColor(value) {
  return String(value || '').match(/\bglossy tape surfaces in ([^,.;]+)/i)?.[1]?.trim()
    || String(value || '').match(/\ball tape wrap bands in ([a-z][a-z -]*)$/i)?.[1]?.trim()
    || '';
}

function buildAiAdhesiveTapeWrapSurfaceLead(value) {
  if (/\bsafety-yellow tape surfaces with repeating bold black uppercase CAUTION lettering and solid black rectangular warning blocks\b/i.test(value || '')) {
    return 'safety-yellow glossy caution tape with repeating bold black uppercase CAUTION lettering and solid black rectangular warning blocks';
  }
  const color = extractAdhesiveTapeWrapColor(value);
  return color ? `${color} glossy adhesive tape` : 'glossy adhesive tape';
}

function buildAiAdhesiveTapeWrapText(value, context = null, { compact = false } = {}) {
  if (!isAdhesiveTapeWrapOutfitPresetSource(value)) return '';

  const projection = getCompositionVisibilityProjection(context);
  const detailZones = new Set(projection?.wardrobe?.detailZones || []);
  const hasVisibleZone = (zone) => detailZones.size === 0 || detailZones.has(zone);
  const parts = [
    `${buildAiAdhesiveTapeWrapSurfaceLead(value)} wrapped directly around the skin in separate wide bands`,
  ];

  if (hasVisibleZone('shoulder') || hasVisibleZone('upperBody')) {
    parts.push('bare shoulders and open upper and lower bust areas');
  }
  if (hasVisibleZone('upperBody')) {
    parts.push(compact
      ? 'independent chest and ribcage wrap bands'
      : 'independent wide chest and ribcage wrap bands');
  }
  if (hasVisibleZone('waist')) {
    parts.push('localized waist and abdomen bands');
  }
  if (hasVisibleZone('hip')) {
    parts.push('independent hip and pelvis wrap bands with overlapping center-front and rear coverage');
  }
  if (hasVisibleZone('thigh')) {
    parts.push('separate thigh wrap bands');
  }

  parts.push(
    'mostly horizontal with natural diagonal overlaps',
    compact ? 'visible skin gaps and compressed skin with soft flesh bulges at the tape edges' : 'visible skin gaps and occasional overlaps, compressed skin with soft flesh bulges and slight spillover along the tape edges',
  );

  return parts.join(', ');
}

const AI_COMPLETE_LOOK_SIGNATURE_PATTERNS = [
  /\bglossy (?:black|skin-tone) latex\b/i,
  /\bsharp mirror reflections\b/i,
  /\bvacuum-tight second-skin fit\b/i,
  /\bfull-length legs\b/i,
  /\bdeep demi-cup neckline\b/i,
  /\blow sweetheart neckline\b/i,
  /\blow-rise high-cut leather briefs\b/i,
  /\bvertical side straps linking the bra to hip and garter bands\b/i,
  /\bblack lace bra\b/i,
  /\bgarter straps\b/i,
];

function compactAiCompleteLookFragment(value) {
  const source = compactAiSourceText(value);
  const wordCount = source.match(/[A-Za-z0-9]+(?:['’-][A-Za-z0-9]+)*/g)?.length || 0;
  const signaturePhrases = AI_COMPLETE_LOOK_SIGNATURE_PATTERNS
    .map((pattern) => source.match(pattern)?.[0] || '')
    .filter(Boolean);
  if (/^(?:bottom|top)\s+button\b/i.test(source) && signaturePhrases.length === 0) return '';
  if (/^(?:two|three|four)\s+chest buttons?\b/i.test(source) && signaturePhrases.length > 0) {
    return signaturePhrases[0];
  }
  if (wordCount <= 12) return source;

  const connectorIndex = source.search(/\b(?:with|featuring|ending|revealing|showing|producing|while|that|providing)\b/i);
  const connectorLead = connectorIndex > 0 ? source.slice(0, connectorIndex).trim() : source;
  const nounLead = source.match(
    /^.*?\b(?:catsuit|bodysuit|dress|gown|shirt|top|tee|camisole|bra|corset|jacket|coat|blazer|cardigan|robe|skirt|shorts|pants|jeans|trousers|briefs|stockings|tights|socks|boots|heels|pumps|sandals|sneakers|loafers|bag|pouch|hat|cap)\b/i
  )?.[0];
  const lead = (connectorLead.match(/[A-Za-z0-9]+(?:['’-][A-Za-z0-9]+)*/g)?.length || 0) <= 18
    ? connectorLead
    : (nounLead || connectorLead);
  const additionalSignatures = signaturePhrases
    .filter((phrase) => !lead.toLowerCase().includes(phrase.toLowerCase()))
    .slice(0, 3);

  return [lead, ...additionalSignatures].filter(Boolean).join(', ');
}

function compactAiCompleteLookRoleFragments(
  fragments,
  role,
  majorRoleLimit = 2,
  fragmentCompactor = compactAiCompleteLookFragment
) {
  const limit = ['top', 'dress', 'bottom', 'outerwear'].includes(role) ? majorRoleLimit : 1;
  return fragments
    .map(fragmentCompactor)
    .filter(Boolean)
    .slice(0, limit);
}

function buildAiCompleteLookCoreText(
  value,
  context = null,
  {
    majorRoleLimit = 2,
    fragmentCompactor = compactAiCompleteLookFragment,
  } = {}
) {
  const adhesiveTapeWrapText = buildAiAdhesiveTapeWrapText(value, context, {
    compact: majorRoleLimit <= 1,
  });
  if (adhesiveTapeWrapText) return adhesiveTapeWrapText;

  const primaryMaterial = compactAiSourceText(value).match(/\bglossy (?:black|skin-tone) latex\b/i)?.[0] || '';
  let styleFragment = '';
  const roleFragments = new Map();
  const includeVisibleAccessoryRoles = true;

  for (const fragment of splitAiSourceFragments(value)) {
    if (isAiSpecialPersonFragment(fragment)) continue;
    if (/\b(?:controlled by|color selection|palette direction|outfit palette|dress palette|coordinated top-to-bottom palette|upper\/main garment|lower or secondary garment|preserving garment structure|accessory separation|material contrast|multi-piece color variation)\b/i.test(fragment)) continue;
    if (/\b(?:the\s+)?(?:\w+\s+)?(?:body|fabric|main color|primary color|catsuit|bodysuit|dress)\s+in\s+[a-z -]+$/i.test(fragment)) continue;

    let role = classifyCompleteLookWardrobeFragment(fragment);
    if (!role && /\b(?:catsuit|bodysuit|jumpsuit|romper)\b/i.test(fragment)) role = 'dress';
    const isStyleFragment = /\b(?:styling|outfit)\b/i.test(fragment)
      || (/\blook\b/i.test(fragment) && !/\bwet-look\b/i.test(fragment));
    if (isStyleFragment && !styleFragment) {
      styleFragment = fragment.replace(/\s+outfit$/i, '');
      continue;
    }
    if (role && !shouldKeepWardrobeRoleForContext(role, context, fragment)) continue;
    if (role) roleFragments.set(role, [...(roleFragments.get(role) || []), fragment]);
  }

  const accessoryFragment = [
    ...(includeVisibleAccessoryRoles ? (roleFragments.get('headAccessory') || []) : []),
    ...(includeVisibleAccessoryRoles ? (roleFragments.get('eyewear') || []) : []),
    ...(includeVisibleAccessoryRoles ? (roleFragments.get('neckAccessory') || []) : []),
    ...(roleFragments.get('bag') || []),
    ...(includeVisibleAccessoryRoles ? (roleFragments.get('earrings') || []) : []),
    ...(includeVisibleAccessoryRoles ? (roleFragments.get('wristAccessory') || []) : []),
    ...(includeVisibleAccessoryRoles ? (roleFragments.get('ring') || []) : []),
    ...(includeVisibleAccessoryRoles ? (roleFragments.get('waistAccessory') || []) : []),
  ].map(fragmentCompactor).filter(Boolean).join(', ');

  return [
    styleFragment,
    primaryMaterial,
    ...compactAiCompleteLookRoleFragments(roleFragments.get('top') || [], 'top', majorRoleLimit, fragmentCompactor),
    ...compactAiCompleteLookRoleFragments(roleFragments.get('dress') || [], 'dress', majorRoleLimit, fragmentCompactor),
    ...compactAiCompleteLookRoleFragments(roleFragments.get('bottom') || [], 'bottom', majorRoleLimit, fragmentCompactor),
    ...compactAiCompleteLookRoleFragments(roleFragments.get('outerwear') || [], 'outerwear', majorRoleLimit, fragmentCompactor),
    ...compactAiCompleteLookRoleFragments(roleFragments.get('legwear') || [], 'legwear', 1, fragmentCompactor),
    ...compactAiCompleteLookRoleFragments(roleFragments.get('shoes') || [], 'shoes', 1, fragmentCompactor),
    accessoryFragment,
  ].filter(Boolean).join(', ');
}

function compactAiCharacterCardHairText(baseHair, variantHair = '', { compact = false } = {}) {
  const guardPattern = /\b(?:never|avoid|do not|must not|locked|controlled by)\b/i;
  const baseFragments = splitAiSourceFragments(baseHair).filter((fragment) => !guardPattern.test(fragment));
  const signatureStreak = compactAiSourceText(baseHair).match(
    /\bone dominant broad [^,;:.]*?face-framing streak\b/i
  )?.[0] || '';
  const dominantBase = compactAiSourceText(baseHair).match(
    /\b(?:the\s+)?(?:black|brown|blonde|silver|red|auburn|chestnut|raven-black)\s+base remains dominant\b/i
  )?.[0] || '';
  const variantFragments = splitAiSourceFragments(variantHair)
    .map((fragment) => fragment
      .replace(/^keep the original hair identity$/i, '')
      .replace(/^add\s+/i, '')
      .replace(/\s+without changing the base hair color or haircut$/i, '')
      .trim())
    .filter(Boolean);

  const compactBaseFragments = baseFragments
    .slice(0, compact ? 1 : 2)
    .map((fragment) => compact
      ? fragment.replace(/\s+(?:falling|flowing|cascading|extending|reaching)\b.*$/i, '').trim()
      : fragment);

  return uniqueAiWardrobeValues([
    ...compactBaseFragments,
    signatureStreak,
    dominantBase,
    ...variantFragments,
  ]).join(', ');
}

function compactAiCharacterCardSkinText(value) {
  const source = compactAiSourceText(value);
  const textureIndex = source.search(/\bwith\b/i);
  return textureIndex > 0 ? source.slice(0, textureIndex).trim() : source;
}

function compactAiCharacterCardMakeupText(value) {
  return compactAiMinimalFragment(value, 1).split(/\s+and\s+/i)[0].trim();
}

function buildAiCharacterCardOutfitCoreText(value, context = null) {
  return filterCompleteLookPromptForFraming(value, context);
}

function buildAiCharacterCardAccessoryText(value, context) {
  const projection = getCompositionVisibilityProjection(context);
  return splitAiSourceFragments(value)
    .filter((fragment) => {
      const role = classifyCompleteLookWardrobeFragment(fragment);
      return role
        ? shouldProjectWardrobeRole(projection, role, fragment)
        : isCompleteWardrobeProjection(projection);
    })
    .join(', ');
}

function buildAiNormalWardrobeText(
  valuesByLabel,
  context,
  wardrobe,
  wardrobeColors,
  { majorRoleLimit = 2 } = {}
) {
  const wardrobeSlots = Array.isArray(wardrobe) ? extractWardrobeSlots(wardrobe) : null;
  const explicitWardrobeFitAnchors = getExplicitWardrobeFitAnchors(context, wardrobeSlots);
  const primarySourceByLabel = wardrobeSlots
    ? {
        Outerwear: buildColoredGrokPrompt(wardrobeSlots.outerwear, wardrobeColors?.outerwearColor, {
          fit: wardrobeSlots.outerwearFit,
        }),
        // A separately targeted fabric color is retained below as a visible wear
        // source; it must not become the selected garment identity itself.
        Top: wardrobeSlots.top?.meta?.wearableColorTarget
          ? normalizeWardrobePromptText(wardrobeSlots.top.en)
          : buildColoredGrokPrompt(wardrobeSlots.top, wardrobeColors?.topColor),
        Pants: buildColoredGrokPrompt(wardrobeSlots.pants, wardrobeColors?.bottomColor),
        Skirt: buildColoredGrokPrompt(wardrobeSlots.skirt, wardrobeColors?.bottomColor),
        Legwear: buildColoredGrokPrompt(wardrobeSlots.legwear, wardrobeColors?.legwearColor),
        Shoes: buildColoredGrokPrompt(wardrobeSlots.shoes, wardrobeColors?.shoesColor),
        'Waist Accessory': buildAccessoryPrompt(wardrobeSlots.waistAccessory),
      }
    : {};
  // Full-body structured sources place the outer layer before its inner garment.
  // Recover that already-projected fragment, never hidden raw wardrobe text.
  const outerwear = firstStructuredValue(valuesByLabel, ['Outerwear'])
    || ['Top', 'Dress'].map(label => {
      const source = firstStructuredValue(valuesByLabel, [label]);
      const boundary = source.indexOf(', layered over ');
      return boundary >= 0 ? source.slice(0, boundary) : '';
    }).find(Boolean) || '';
  const shoulderWear = wardrobeSlots?.outerwearStyling;
  const outerwearWearSources = [
    isFullyClosedOpening(wardrobeSlots?.outerwearOpening) ? fullyClosedOuterwearText(wardrobeSlots.outerwear)
      : !isNoneLikeItem(wardrobeSlots?.outerwearOpening) ? normalizeWardrobePromptText(wardrobeSlots?.outerwearOpening?.en || '') : '',
    buildOuterwearStylingLeadText(shoulderWear),
  ];
  const outerwearPatternSource = !isNoneLikeItem(wardrobeSlots?.outerwearPattern)
    ? normalizeWardrobePromptText(wardrobeSlots?.outerwearPattern?.en || '') : '';
  const visibleOuterwear = shouldKeepWardrobeRoleForContext('outerwear', context, outerwear)
    ? compactAiGarmentValue(outerwear, 'outerwear', primarySourceByLabel.Outerwear, outerwearWearSources, outerwearPatternSource)
    : '';
  const visibleCompleteLookWaistAccessory = wardrobeSlots?.waistAccessory
    && !isNoneLikeItem(wardrobeSlots.waistAccessory)
    && shouldKeepWardrobeRoleForContext(
      'waistAccessory',
      context,
      buildAccessoryPrompt(wardrobeSlots.waistAccessory),
    )
    ? compactAiSelectedAccessoryText(wardrobeSlots.waistAccessory, 'waistAccessory')
    : '';
  const withVisibleCompleteLookAddons = (mainWardrobe) => uniqueAiWardrobeValues([
    visibleOuterwear,
    mainWardrobe,
    visibleCompleteLookWaistAccessory,
  ]).join(', ');
  const withExplicitFitAnchors = (mainWardrobe) => appendMissingExplicitWardrobeFitAnchors(
    mainWardrobe,
    explicitWardrobeFitAnchors,
  );

  const specialOutfit = firstStructuredValue(valuesByLabel, ['Special Outfit']);
  if (specialOutfit) {
    return withExplicitFitAnchors(withVisibleCompleteLookAddons(buildAiCompleteLookCoreText(specialOutfit, context, { majorRoleLimit })));
  }

  const outfitPreset = firstStructuredValue(valuesByLabel, ['Outfit Preset']);
  if (outfitPreset) {
    return withExplicitFitAnchors(withVisibleCompleteLookAddons(buildAiCompleteLookCoreText(outfitPreset, context, { majorRoleLimit })));
  }

  const dress = firstStructuredValue(valuesByLabel, ['Dress']);
  if (dress) {
    return withExplicitFitAnchors(withVisibleCompleteLookAddons(buildAiCompleteLookCoreText(dress, context, { majorRoleLimit })));
  }

  const roleByLabel = {
    Outerwear: 'outerwear',
    Top: 'top',
    Pants: 'bottom',
    Skirt: 'bottom',
    Legwear: 'legwear',
    Shoes: 'shoes',
    'Waist Accessory': 'waistAccessory',
  };
  return withExplicitFitAnchors(Object.entries(roleByLabel)
    .map(([label, role]) => {
      const value = role === 'outerwear' ? outerwear : firstStructuredValue(valuesByLabel, [label]);
      const topPatternSource = role === 'top' && wardrobeSlots?.topPattern && !isNoneLikeItem(wardrobeSlots.topPattern)
        ? normalizeWardrobePromptText(wardrobeSlots.topPattern.en) : '';
      const wearSources = role === 'outerwear' ? outerwearWearSources
        : role === 'top' ? [
          isHemOverlapStyling(wardrobeSlots?.topStyling) || wardrobeSlots?.topStyling?.meta?.underbustTopStyle ? wardrobeSlots?.topStyling?.en : '',
          isUnderbustTopFit(wardrobeSlots?.topFit) ? wardrobeSlots.topFit.en : '',
          getItemWearableColorTargetSource(wardrobeSlots?.top, wardrobeColors?.topColor),
        ].filter(Boolean) : [];
      return shouldKeepWardrobeRoleForContext(role, context, value)
        ? compactAiGarmentValue(value, role, primarySourceByLabel[label], wearSources, role === 'outerwear' ? outerwearPatternSource : topPatternSource)
        : '';
    })
    .filter(Boolean)
    .join(', '));
}

function buildAiCharacterCardIdentityText(context, wardrobe, { compact = false } = {}) {
  const groups = buildCharacterCardProfileGroups(context.subject, context.locks, wardrobe);
  const detailedFace = [
    groups.facialGeometry,
    groups.eyeSignature,
    groups.noseSignature,
    groups.mouthSignature,
  ].filter(Boolean);
  const faceText = groups.distinctiveFeatures
    || detailedFace.join(', ');
  const identityText = [
    faceText,
    compactAiCharacterCardSkinText(groups.skinSignature),
    compact ? '' : compactAiCharacterCardMakeupText(groups.makeup),
    compact
      ? compactAiMinimalFragment(groups.body, 1).replace(/\s+with\s+.*$/i, '').trim()
      : groups.body,
  ].filter(Boolean).join(', ');
  const fallbackIdentityText = identityText
    ? identityText
    : groups.identityAndBody;
  const hairText = compactAiCharacterCardHairText(
    groups.hair,
    buildCharacterCardHairVariantText(context.subject, context.locks),
    { compact }
  );
  const eyewearText = splitAiSourceFragments(groups.accessories)
    .filter((fragment) => /\b(?:glasses|eyeglasses|sunglasses|headphones?|earphones?)\b/i.test(fragment))
    .join(', ');

  return [
    '20-year-old East Asian woman',
    compactAiSourceText(fallbackIdentityText),
    hairText,
    eyewearText,
  ].filter(Boolean).join(', ');
}

function normalizeAiCharacterCardSource(value) {
  return stripMarkdown(value || '')
    .replace(/[.!?]+$/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function removeCharacterCardWardrobeValues(valuesByLabel, context, wardrobe) {
  if (!(valuesByLabel instanceof Map)) return valuesByLabel;

  const cardLayerLabels = {
    outerwear: ['Outerwear'],
    dress: ['Dress'],
    top: ['Top'],
    bottom: ['Pants', 'Skirt'],
    legwear: ['Legwear'],
    shoes: ['Shoes'],
    waistAccessory: ['Waist Accessory'],
  };
  const ownedLabels = new Set(
    (wardrobe || [])
      .filter((item) => item?.meta?.characterCardLayer)
      .flatMap((item) => cardLayerLabels[item.meta.characterCardLayer] || [])
  );
  const cardSources = new Set(
    getCharacterCardWardrobeSourceTexts(context.subject, context.locks, wardrobe)
      .map(normalizeAiCharacterCardSource)
      .filter(Boolean)
  );
  if (cardSources.size === 0 && ownedLabels.size === 0) return valuesByLabel;

  return new Map(
    [...valuesByLabel.entries()]
      .filter(([label]) => !ownedLabels.has(label))
      .map(([label, values]) => [
        label,
        (values || []).filter((value) => !cardSources.has(normalizeAiCharacterCardSource(value))),
      ])
      .filter(([, values]) => values.length > 0)
  );
}

const AI_CHARACTER_CARD_OUTFIT_LAYERS = new Set([
  'outerwear',
  'dress',
  'top',
  'bottom',
  'legwear',
  'shoes',
]);

const AI_CHARACTER_CARD_ACCESSORY_LAYERS = new Set([
  'headAccessory',
  'eyewear',
  'earrings',
  'neckAccessory',
  'wristAccessory',
  'ring',
  'waistAccessory',
]);

function getAiCharacterCardLayerSources(context, wardrobe) {
  if (!isCharacterProfileSubject(context?.subject)) return [];
  const slots = extractWardrobeSlots(wardrobe || []);
  const hideInner = isFullyClosedOpening(slots.outerwearOpening)
    && slots.outerwear && !closedInnerLayerIsVisible(slots.outerwear);

  const card = getRuntimeCharacterCards().find((entry) => entry.id === context.subject.id);
  if (!card) return [];

  const variant = getCharacterCardVariantFromLocks({
    ...(context.locks || {}),
    characterProfileId: context.subject.id,
  });
  const layerMap = getEffectiveCharacterCardWardrobeLayers(card, variant);
  const included = new Set(
    shouldImportCharacterCardWardrobeLayers(context.locks)
      ? variant.includedWardrobeLayers || []
      : Object.keys(layerMap)
  );
  const importedSourceByLayer = new Map(
    (wardrobe || [])
      .filter((item) => item?.meta?.characterCardLayer)
      .map((item) => [item.meta.characterCardLayer, item.en])
  );

  return [
    'outerwear',
    'dress',
    'top',
    'bottom',
    'legwear',
    'shoes',
    'headAccessory',
    'eyewear',
    'earrings',
    'neckAccessory',
    'wristAccessory',
    'ring',
    'waistAccessory',
  ]
    .filter((key) => included.has(key) && layerMap[key] && !(hideInner && key === 'top'))
    .map((key) => ({
      key,
      source: hideInner && key === 'dress'
        ? projectClosedInnerLook(importedSourceByLayer.get(key) || layerMap[key].prompt)
        : importedSourceByLayer.get(key) || layerMap[key].prompt,
    }))
    .filter((entry) => entry.source);
}

function buildAiCharacterCardPage1AccessoryText(context, wardrobe) {
