}

function buildAiSingleFaceExpressionText(valuesByLabel, context, character) {
  if (!shouldUseFixedAiSingleSubjectLead(context)) return '';

  const characterSlots = extractCharacterSlots(Array.isArray(character) ? character : []);
  const facialFeaturesItem = characterSlots.facialFeatures && !isNoneLikeItem(characterSlots.facialFeatures)
    ? characterSlots.facialFeatures
    : null;
  const facialFeaturesText = facialFeaturesItem?.en || firstStructuredValue(valuesByLabel, ['Facial Features']);
  const expressionText = characterSlots.expression && !isNoneLikeItem(characterSlots.expression)
    ? resolvePromptVariant(characterSlots.expression, 'expression', context.subject.count)
    : firstStructuredValue(valuesByLabel, ['Expression']);
  const facialAnchor = compactAiMinimalFragment(
    facialFeaturesItem?.mj?.face || facialFeaturesText,
    facialFeaturesItem?.mj?.face ? 3 : 1,
  );
  const expressionFragments = splitAiSourceFragments(expressionText)
    .map((fragment) => fragment.replace(
      /\b(lips?[^,]*?)\s+with\s+(?:a\s+)?([^,]+(?:smile|grin)[^,]*)$/i,
      '$1, $2'
    ));
  const selectedExpressionFragments = [];
  const addExpressionFragment = (fragment) => {
    if (!fragment) return;
    const normalized = fragment.toLowerCase();
    if (selectedExpressionFragments.some((existing) => existing.toLowerCase() === normalized)) return;
    selectedExpressionFragments.push(fragment);
  };

  expressionFragments.forEach(addExpressionFragment);

  const compactExpression = selectedExpressionFragments.join(', ');
  return [facialAnchor, compactExpression].filter(Boolean).join(', ');
}

function buildAiFreedomSubjectSentence(
  valuesByLabel,
  context,
  wardrobe,
  character,
  wardrobeColors,
  { compact = false } = {}
) {
  if (isCharacterProfileSubject(context.subject)) {
    return ensureTerminalPeriod(buildAiCharacterCardIdentityText(context, wardrobe, { compact }));
  }

  const wardrobeSlots = Array.isArray(wardrobe) ? extractWardrobeSlots(wardrobe) : null;
  const specialOutfitText = firstStructuredValue(valuesByLabel, ['Special Outfit'])
    || buildSpecialOutfitPrompt(wardrobeSlots?.specialOutfit);
  const specialPersonText = specialOutfitText
    ? extractAiSpecialPersonFragments(specialOutfitText, context).join(', ')
    : '';
  const structuredHeadAccessory = firstStructuredValue(valuesByLabel, ['Head Accessory']);
  const headAccessoryText = wardrobeSlots
    ? compactAiHeadAccessoryText(
        structuredHeadAccessory || wardrobeSlots.headAccessory,
        structuredHeadAccessory ? null : wardrobeColors?.headAccessoryColor,
      )
    : compactAiHeadAccessoryText(firstStructuredValue(valuesByLabel, ['Head Accessory']));
  const faceAccessoryText = buildAiRoleFaceAccessoryText(wardrobeSlots);
  const subjectLead = shouldUseFixedAiSingleSubjectLead(context)
    ? MIDJOURNEY_FIXED_SINGLE_NORMAL_SUBJECT_LEAD
    : buildMidjourneySpecialSubjectPrompt(context.subject, context) || 'A 20-year-old adult East Asian woman';

  const bodyText = shouldUseFixedAiSingleSubjectLead(context)
    ? buildAiSingleBodyTypeAnchorText(valuesByLabel, context)
    : compactAiBodyTypeAnchorText(firstStructuredValue(valuesByLabel, ['Body Type']));
  const hairText = shouldUseFixedAiSingleSubjectLead(context)
    ? buildAiSingleHairAnchorText(valuesByLabel, context, { compact })
    : compactAiSourceText([
        firstStructuredValue(valuesByLabel, ['Hairstyle']),
        firstStructuredValue(valuesByLabel, ['Hair Styling State']),
        firstStructuredValue(valuesByLabel, ['Hair Color']),
      ].filter(Boolean).join(', '));
  const faceExpressionText = buildAiSingleFaceExpressionText(valuesByLabel, context, character);

  const subjectText = [
    shouldUseFixedAiSingleSubjectLead(context)
      ? ensureTerminalPeriod(subjectLead)
      : stripTerminalPromptPunctuation(subjectLead),
    [
      bodyText,
      hairText,
      faceExpressionText,
      specialPersonText,
      faceAccessoryText,
      headAccessoryText,
    ].filter(Boolean).join(', '),
  ].filter(Boolean).join(shouldUseFixedAiSingleSubjectLead(context) ? ' ' : ', ')
    .replace(/\.\s*,/g, ',')
    .replace(/,\s*\./g, '.')
    .replace(/\s*,\s*,+/g, ', ');
  return ensureTerminalPeriod(subjectText);
}

function buildAiFreedomWardrobeSentence(
  valuesByLabel,
  context,
  wardrobe,
  wardrobeColors,
  { compact = false } = {}
) {
  const characterCardMode = isCharacterProfileSubject(context.subject);
  const characterCardGroups = characterCardMode
    ? buildCharacterCardProfileGroups(context.subject, context.locks, wardrobe)
    : null;
  const characterCardLayerSources = characterCardMode
    ? getAiCharacterCardLayerSources(context, wardrobe)
    : [];
  const page1Wardrobe = characterCardMode && Array.isArray(wardrobe)
    ? wardrobe.filter((item) => !item?.meta?.characterCardLayer)
    : wardrobe;
  const page1ValuesByLabel = characterCardMode
    ? removeCharacterCardWardrobeValues(valuesByLabel, context, wardrobe)
    : valuesByLabel;
  const cardOutfitSourceText = characterCardMode
    ? characterCardLayerSources
      .filter((entry) => AI_CHARACTER_CARD_OUTFIT_LAYERS.has(entry.key))
      .map((entry) => entry.source)
      .concat(
        characterCardLayerSources.some((entry) => AI_CHARACTER_CARD_OUTFIT_LAYERS.has(entry.key))
          ? []
          : [characterCardGroups.outfit]
      )
      .filter(Boolean)
      .join(', ')
    : '';
  const cardOutfitText = cardOutfitSourceText
    ? buildAiCharacterCardOutfitCoreText(cardOutfitSourceText, context)
    : '';
  const selectedCardFillers = characterCardMode && shouldImportCharacterCardWardrobeLayers(context.locks)
    ? buildAiNormalWardrobeText(
        page1ValuesByLabel,
        context,
        page1Wardrobe,
        wardrobeColors,
        { majorRoleLimit: compact ? 1 : 2 }
      )
    : '';
  const characterCardAccessories = characterCardMode
    ? buildAiCharacterCardAccessoryText(
        [
          ...characterCardLayerSources
            .filter((entry) => AI_CHARACTER_CARD_ACCESSORY_LAYERS.has(entry.key))
            .map((entry) => entry.source),
          buildAiCharacterCardPage1AccessoryText(context, wardrobe),
        ]
          .filter(Boolean)
          .join(', ')
          .split(', ')
          .filter((fragment) => !/\b(?:glasses|eyeglasses|sunglasses|headphones?|earphones?)\b/i.test(fragment))
          .join(', '),
        context
      )
    : '';
  const wardrobeParts = characterCardMode
    ? [
        cardOutfitText,
        selectedCardFillers,
        characterCardAccessories,
      ]
    : [buildAiNormalWardrobeText(
        valuesByLabel,
        context,
        wardrobe,
        wardrobeColors,
        { majorRoleLimit: compact ? 1 : 2 }
      )];
  const protectedLayerSources = protectNewLayeredHemSources(wardrobeParts.join(', '));
  const wardrobeText = protectedLayerSources.restore(uniqueAiWardrobeValues(protectedLayerSources.text.split(/,\s*/)).join(', '));
  const visibleWardrobeText = stripAiUpperCropBoundaryText(wardrobeText, context);
  const visibleFitAnchors = getExplicitWardrobeFitAnchors(
    context,
    Array.isArray(wardrobe) ? extractWardrobeSlots(wardrobe) : null,
  );
  const finalWardrobeText = appendMissingExplicitWardrobeFitAnchors(
    dedupeAiLowerCropBoundary(visibleWardrobeText),
    visibleFitAnchors,
  );
  return finalWardrobeText ? ensureTerminalPeriod(`Wearing ${finalWardrobeText}`) : '';
}

function buildAiFreedomPoseSentence(context, character) {
  if (context.subject?.count !== 1) return '';
  const characterSlots = extractCharacterSlots(character);
  const poseComposer = characterSlots.poseComposer;
  if (!poseComposer || isNoneLikeItem(poseComposer)) return '';
  return ensureTerminalPeriod(stripMarkdown(context.projectedCanonicalPoseText || '').replace(/\s+/g, ' ').trim());
}

function buildAiFreedomSceneSentence(valuesByLabel, context, { maxClauses = 3, part = 'all' } = {}) {
  if (isCarriageFixedSet(context.carriageFixedSceneSource)) return carriageSceneText(context.carriageFixedSceneSource,
    { compact: true, background: context.fixedSetBackgroundState });
  if (isStationFixedSet(context.stationFixedSceneSource)) return [
    stationSceneText(context.stationFixedSceneSource, { compact: true }),
  ].filter(Boolean).join(' ');
  if (isFixedCompositionSetActive(context?.fixedCompositionSet)) {
    if (isStationFixedSet(context.fixedCompositionSet) || isCarriageFixedSet(context.fixedCompositionSet)) return buildAiFixedCompositionSceneClause(context);
    const fixedScene = AI_FIXED_SET_SCENE_PHRASES[context.fixedCompositionSet?.id] || '';
    return fixedScene ? ensureTerminalPeriod(capitalizePromptLead(compactAiSourceText(fixedScene))) : '';
  }

  const sceneSource = context.projectedScene?.worldSceneText
    || context.projectedScene?.locationText
    || firstStructuredValue(valuesByLabel, ['World Scene Architecture'])
    || firstStructuredValue(valuesByLabel, ['Location']);
  let clauses = splitAiSourceFragments(sceneSource);
  if (clauses.length < 2 && context.location && !isNoneLikeItem(context.location)) {
    const sceneMode = context.compositionVisibility?.scene?.mode === 'conciseSource'
      ? 'conciseSource'
      : 'compactSource';
    const projectedLocationFallback = projectSceneSourceText(context.location.en, sceneMode);
    const fallbackClauses = splitAiSourceFragments(projectedLocationFallback);
    if (fallbackClauses.length > clauses.length) clauses = fallbackClauses;
  }
  const conditionPattern = /\b(?:rain|snow|storm|fog|mist|wind|night|dusk|dawn|sunset|sunrise|daylight|overcast|cloudy|golden hour|post-rain|winter|summer|spring|autumn|late-afternoon|early-morning)\b/i;
  const physicalAnchorPattern = /\b(?:room|bed|cabinet|locker|sink|tiles?|shelf|table|desk|chair|sofa|window|door|wall|floor|counter|bench|curtain|railing|pavement|stair|books?|lamp|fixture|debris|foliage|plants?|trees?)\b/i;
  const primary = clauses[0] || '';
  const physicalAnchor = clauses.find((clause, index) => index > 0 && physicalAnchorPattern.test(clause));
  const condition = clauses.find((clause) => conditionPattern.test(clause));
  const selected = [primary, physicalAnchor, condition, ...clauses]
    .filter(Boolean)
    .filter((clause, index, all) => all.findIndex((item) => item.toLowerCase() === clause.toLowerCase()) === index)
    .slice(0, maxClauses);

  const visibleClauses = part === 'identity' ? selected.slice(0, 1)
    : part === 'details' ? selected.slice(1) : selected;
  const sceneText = visibleClauses.join(', ')
    .replace(/\bThe portrait takes place (?:inside|within) a real-scale [^,]+? set\b/gi, '')
    .replace(/,?\s*not a flat backdrop and not a tight subject portrait/gi, '')
    .replace(/,?\s*not a generic beach scene/gi, '')
    .replace(/,?\s*Treat the fixed set as the primary composition:?/gi, '')
    .replace(/,?\s*the camera is positioned[^,]*(?:,|$)/gi, '')
    .replace(/,?\s*Scene priority:[^,]*/gi, '')
    .replace(/\s*,\s*,+/g, ', ')
    .replace(/,\s*\./g, '.')
    .trim();
  return sceneText ? ensureTerminalPeriod(capitalizePromptLead(sceneText)) : '';
}

function buildAiFreedomLightingText(valuesByLabel, { compact = false } = {}) {
  const ambient = compactAiSourceText(compactPromptClauses(
    firstStructuredValue(valuesByLabel, ['Ambient Light Conditions']),
    compact ? 1 : 2
  ));
  const subjectLight = compactAiSourceText(compactPromptClauses(
    firstStructuredValue(valuesByLabel, ['Subject Light Style']),
    compact ? 1 : 3
  ));
  return [ambient, subjectLight].filter(Boolean).join(', ');
}

function buildAiFreedomSceneWithLightingSentence(
  valuesByLabel,
  context,
  { maxSceneClauses = 4, compactLighting = false, part = 'all' } = {}
) {
  const scene = buildAiFreedomSceneSentence(valuesByLabel, context, { maxClauses: maxSceneClauses, part });
  const lighting = buildAiFreedomLightingText(valuesByLabel, { compact: compactLighting });
  const lightingSentence = lighting
    ? ensureTerminalPeriod(capitalizePromptLead(lighting))
    : '';
  if (!scene) return lightingSentence;
  if (!lighting) return scene;
  return `${scene} ${lightingSentence}`;
}

function buildAiFreedomImagingSentence(
  valuesByLabel,
  { compact = false, characterCard = false, adaptation = null, sceneIntegrated = false, stationFixed = false } = {}
) {
  const styleText = sceneIntegrated ? '' : firstStructuredValue(valuesByLabel, ['Photography Style']);
  const style = (
    styleText.match(/Inspired by [^.]+? image language/i)?.[0]
    || compactPromptClauses(styleText, 1)
  ).replace(/^Inspired by ([^,]+),\s*/i, '$1-inspired ');
  const lens = compactPromptClauses(
    firstStructuredValue(valuesByLabel, ['Lens']),
    stationFixed ? 6 : compact && !characterCard ? 1 : 2
  ).replace(/^shot on\s+/i, '');
  const lensAdaptation = (adaptation?.imagingAdditions || [])
    .filter((addition) => !stationFixed || !lens.toLowerCase().split(/\s*,\s*/).includes(addition.toLowerCase()))
    .join(', ');
  const parts = [
    style,
    lens,
    lensAdaptation,
    ...(sceneIntegrated ? [
      compactPromptClauses(firstStructuredValue(valuesByLabel, ['Aperture / Depth of Field']), 1),
      compactPromptClauses(firstStructuredValue(valuesByLabel, ['Shutter / Motion Blur']), 1),
    ] : []),
    compactPromptClauses(firstStructuredValue(valuesByLabel, ['Optical Effect']), 1),
    sceneIntegrated ? '' : compactPromptClauses(firstStructuredValue(valuesByLabel, ['Camera / Film']), compact ? 1 : 2),
  ].map((value) => compactAiSourceText(value)).filter(Boolean);
  return parts.length > 0 ? ensureTerminalPeriod(parts.join(', ')) : '';
}

const AI_LEGACY_SINGLE_RENDERER_HELPERS = [
