// Legacy compact AI renderer. Its last caller, the MJ chest-up output, was removed
// on 2026-10-14; delete this chain in a dedicated dead-code cleanup, not here.
// eslint-disable-next-line no-unused-vars
function renderAiPrompt(promptModel, {
  compositionPromptModel = promptModel,
  subjectPromptModel = promptModel,
  wardrobePromptModel = promptModel,
  posePromptModel = promptModel,
  scenePromptModel = promptModel,
  imagingPromptModel = promptModel,
  midjourneyAdaptation = null,
  integrateMainScene = false,
  sceneMirrorReflectionText = '',
} = {}) {
  const {
    valuesByLabel,
    context,
    character,
    wardrobe,
    wardrobeColors,
  } = promptModel;

  if (context.subject?.count === 2 && !isSpecialSubject(context.subject)) {
    return renderAiDuoPrompt(valuesByLabel, context, wardrobe, wardrobeColors, {
      adaptation: midjourneyAdaptation,
    });
  }

  const subjectValuesByLabel = subjectPromptModel.valuesByLabel || valuesByLabel;
  const subjectContext = subjectPromptModel.context || context;
  const subjectWardrobe = subjectPromptModel.wardrobe || wardrobe;
  const subjectCharacter = subjectPromptModel.character || character;
  const wardrobeValuesByLabel = wardrobePromptModel.valuesByLabel || valuesByLabel;
  const wardrobeContext = wardrobePromptModel.context || context;
  const wardrobeSource = wardrobePromptModel.wardrobe || wardrobe;
  const wardrobeColorSource = wardrobePromptModel.wardrobeColors || wardrobeColors;
  const poseContext = posePromptModel.context || context;
  const poseCharacter = posePromptModel.character || character;
  const compositionContext = compositionPromptModel.context || context;
  const sceneValuesByLabel = scenePromptModel.valuesByLabel || valuesByLabel;
  const sceneContext = scenePromptModel.context || context;
  const imagingValuesByLabel = imagingPromptModel.valuesByLabel || valuesByLabel;

  // Main MJ and its same-state chest derivative opt into the same assembly;
  // excluded subject and capture modes retain their existing semantics.
  const poseComposer = extractCharacterSlots(character).poseComposer;
  const anchor = getPoseComposerOption(POSE_COMPOSER_ANCHOR_OPTIONS, poseComposer?.meta?.poseAnchorId);
  const supineSurfaceLed = poseComposer?.meta?.poseBaseId === 'lying'
    && poseComposer?.meta?.poseOrientationId === 'lying-supine'
    && (anchor?.meta?.supineSurfaceLed === true || poseComposer?.meta?.supineGroundOnly === true);
  const sceneIntegrated = integrateMainScene && context.subject?.count === 1
    && !isSpecialSubject(context.subject) && !isCharacterProfileSubject(context.subject)
    && !context.characterProfilePrompt
    && !isFixedCompositionSetActive(context.fixedCompositionSet)
    && !isStationFixedSet(context.stationFixedSceneSource) && !supineSurfaceLed;

  const policyKey = resolveAiPromptPolicyKey({
    characterCard: isCharacterProfileSubject(context.subject),
    completeLook: Boolean(
      firstStructuredValue(valuesByLabel, ['Special Outfit'])
      || firstStructuredValue(valuesByLabel, ['Outfit Preset'])
      || firstStructuredValue(valuesByLabel, ['Dress'])
    ),
  });
  const sceneIdentity = sceneIntegrated
    ? buildAiFreedomSceneSentence(sceneValuesByLabel, sceneContext, { maxClauses: 4, part: 'identity' }) : '';
  const fullSceneText = buildAiFreedomSceneWithLightingSentence(sceneValuesByLabel, sceneContext, {
    part: sceneIntegrated ? 'details' : 'all',
  });
  const compactSceneText = buildAiFreedomSceneWithLightingSentence(sceneValuesByLabel, sceneContext, {
    maxSceneClauses: 2,
    compactLighting: true,
    part: sceneIntegrated ? 'details' : 'all',
  });
  const adaptation = midjourneyAdaptation;
  const stationFixed = isStationFixedSet(context.fixedCompositionSet) || isStationFixedSet(context.stationFixedSceneSource)
    || isCarriageFixedSet(context.fixedCompositionSet) || isCarriageFixedSet(context.carriageFixedSceneSource);
  const fullImagingText = buildAiFreedomImagingSentence(imagingValuesByLabel, { adaptation, sceneIntegrated, stationFixed });
  const compactImagingText = buildAiFreedomImagingSentence(imagingValuesByLabel, {
    compact: true,
    characterCard: policyKey === 'characterCard',
    adaptation,
    sceneIntegrated,
    stationFixed,
  });
  const fullWardrobeText = buildAiFreedomWardrobeSentence(
    wardrobeValuesByLabel,
    wardrobeContext,
    wardrobeSource,
    wardrobeColorSource,
  );
  const compactWardrobeText = buildAiFreedomWardrobeSentence(
    wardrobeValuesByLabel,
    wardrobeContext,
    wardrobeSource,
    wardrobeColorSource,
    { compact: true },
  );
  const sceneReductions = isCompleteWardrobeProjection(getCompositionVisibilityProjection(sceneContext))
    && policyKey !== 'characterCard'
    ? []
    : [compactSceneText];
  const fullSubjectText = buildAiFreedomSubjectSentence(
    subjectValuesByLabel,
    subjectContext,
    subjectWardrobe,
    subjectCharacter,
    wardrobeColorSource,
  );
  const compactSubjectText = buildAiFreedomSubjectSentence(
    subjectValuesByLabel,
    subjectContext,
    subjectWardrobe,
    subjectCharacter,
    wardrobeColorSource,
    { compact: true },
  );
  const sectionDefinitions = [
    { id: 'imageType', text: buildMidjourneyImageTypePromptLine(compositionContext) },
    {
      id: 'composition',
      text: [sceneIdentity ? `The setting is ${sceneIdentity}` : '', sceneMirrorReflectionText ? ensureTerminalPeriod(sceneMirrorReflectionText) : '', joinCompositionPromptText(
        ensureTerminalPeriod(buildCompositionPromptLine(compositionContext, { adaptation })),
        extractCharacterSlots(poseCharacter).poseComposer,
      )].filter(Boolean).join(' '),
    },
    {
      id: 'subject',
      text: fullSubjectText,
      reductions: [compactSubjectText],
    },
    {
      id: 'wardrobe',
      text: fullWardrobeText,
      reductions: [compactWardrobeText],
    },
    { id: 'projectedCanonicalPose', text: buildAiFreedomPoseSentence(poseContext, poseCharacter) },
    {
      id: 'scene',
      text: fullSceneText,
      reductions: sceneReductions,
    },
    {
      id: 'imaging',
      text: fullImagingText,
      reductions: [compactImagingText],
    },
  ];
  const sectionModel = createAiPromptSectionModel({
    policyKey,
    sections: sectionDefinitions,
    sceneIntegrated,
  });
  return renderAiPromptSectionModel(sectionModel);
}

// Main MJ owns this projection. The legacy AI renderer remains the unchanged
// same-state chest renderer; never pass this policy into shared source builders.
function buildNaturalMjWardrobe(promptModel, role = '') {
  const { context, wardrobe, wardrobeColors, valuesByLabel } = promptModel;
  const slots = extractWardrobeSlots(wardrobe);
  const projection = getCompositionVisibilityProjection(context);
  const names = [];
  const addSource = source => names.push(...extractMidjourneyItemNames(source));
  const addPreset = (item, source, suffix = '') => {
    if (!item?.meta?.shirtBlackBottom) { addSource(source); return; }
    // Read only surviving projected garment identities. In particular, do not
    // recreate the shirt behind a closed coat or a bottom outside the crop.
    const shirt = String(source || '').match(/\b(short|long)-sleeve button-up shirt\b/i)?.[0];
    if (shirt) {
      const color = wardrobeColors[`outfitPreset${suffix}PrimaryColor`] || wardrobeColors[`outfitPreset${suffix}Color`];
      names.push(composeWearableColorPrompt(shirt, color).replace(/,\s*/g, ' '));
    }
    if (/\bblack hot pants\b/i.test(source)) names.push('black hot pants');
    if (/\bblack bodycon mini skirt\b/i.test(source)) names.push('black bodycon mini skirt');
  };
  const addItem = (item, wardrobeRole) => {
    if (item && !isNoneLikeItem(item) && !(isCharacterProfileSubject(context.subject) && isCharacterCardLayerSlot(item))
      && shouldProjectWardrobeRole(projection, wardrobeRole, item.en)) {
      names.push(midjourneyItemName(item));
      if (wardrobeRole === 'legwear' && /lace garter belt/i.test(item.en)) names.push('lace garter belt');
    }
  };
  if (isDedicatedSpecialSubject(context.subject)) {
    if (['european-knight', 'sengoku-samurai'].includes(context.subject.id)) addSource(buildMidjourneySpecialSubjectPrompt(context.subject, context));
    return uniqueNames(names).join(', ');
  }
  if (role) {
    const suffix = role === 'a' ? 'A' : 'B';
    const roleSpecial = slots[`specialOutfit${suffix}`];
    const special = roleSpecial && !isNoneLikeItem(roleSpecial) ? roleSpecial : slots.specialOutfit;
    if (special && !isNoneLikeItem(special)) {
      addSource(buildGptDuoSpecialOutfitText(special, wardrobeColors[`completeLookPalette${suffix}`] || wardrobeColors.completeLookPalette, context));
    } else {
      const hasRoleMain = ['outfitPreset', 'dress', 'top', 'pants', 'skirt']
        .some(key => slots[`${key}${suffix}`] && !isNoneLikeItem(slots[`${key}${suffix}`]));
      const mainSuffix = hasRoleMain ? suffix : '';
      const preset = slots[`outfitPreset${mainSuffix}`];
      if (preset && !isNoneLikeItem(preset)) {
        addPreset(preset, hasRoleMain ? buildGptDuoRoleMainWardrobeText(slots, wardrobeColors, role, context)
          : buildGptDuoSharedMainWardrobeText(slots, wardrobeColors, context), mainSuffix);
      } else {
        const dress = slots[`dress${mainSuffix}`];
        addItem(dress, 'dress');
        if (!dress || isNoneLikeItem(dress)) {
          addItem(slots[`top${mainSuffix}`], 'top');
          addItem(slots[`pants${mainSuffix}`], 'bottom');
          addItem(slots[`skirt${mainSuffix}`], 'bottom');
        }
      }
      for (const key of ['outerwear', 'legwear', 'shoes', 'waistAccessory']) {
        addItem(slots[`${key}${suffix}`], key);
        addItem(slots[key], key);
      }
    }
  } else if (isCharacterProfileSubject(context.subject)) {
    for (const layer of getAiCharacterCardLayerSources(context, wardrobe)) {
      const source = filterCompleteLookPromptForFraming(layer.source, context);
      const reviewed = MIDJOURNEY_CARD_ITEM_NAMES[context.subject.id]?.[layer.key];
      if (source) names.push(...(reviewed ? reviewed.split(', ') : extractMidjourneyItemNames(source)));
    }
    // Selected card layers may be combined with PAGE1 garments in the vacant slots.
    // These are already resolved/projected; card-owned slots are skipped by addItem.
    for (const [key, wardrobeRole] of [['dress', 'dress'], ['top', 'top'], ['pants', 'bottom'], ['skirt', 'bottom'],
      ['outerwear', 'outerwear'], ['legwear', 'legwear'], ['shoes', 'shoes'], ['waistAccessory', 'waistAccessory']]) {
      addItem(slots[key], wardrobeRole);
    }
  } else {
    const complete = firstStructuredValue(valuesByLabel, ['Special Outfit', 'Outfit Preset']);
    if (complete) {
      if (firstStructuredValue(valuesByLabel, ['Special Outfit'])) addSource(complete);
      else addPreset(slots.outfitPreset, complete);
    }
    else {
      addItem(slots.dress, 'dress');
      if (!slots.dress || isNoneLikeItem(slots.dress)) {
        addItem(slots.top, 'top');
        addItem(slots.pants, 'bottom');
        addItem(slots.skirt, 'bottom');
      }
    }
    addItem(slots.outerwear, 'outerwear');
    if (!slots.specialOutfit || isNoneLikeItem(slots.specialOutfit)) {
      addItem(slots.legwear, 'legwear');
      addItem(slots.shoes, 'shoes');
      addItem(slots.waistAccessory, 'waistAccessory');
    }
  }
  const suffix = role === 'a' ? 'A' : role === 'b' ? 'B' : '';
  for (const key of ['headAccessory', 'eyewear', 'earrings', 'neckAccessory', 'headphones', 'faceCovering', 'nosePiercing', 'lipPiercing']) {
    const item = slots[`${key}${suffix}`] || slots[key];
    addItem(item, ['headphones', 'faceCovering', 'nosePiercing', 'lipPiercing'].includes(key) ? 'eyewear' : key);
  }
  return uniqueNames(names).join(', ');
}

function buildNaturalMjSubject(promptModel) {
  if (promptModel.context.referencePersonPreview) {
    return naturalSentence([promptModel.context.subject.en, firstStructuredValue(promptModel.valuesByLabel, ['Expression'])].filter(Boolean).join(', '));
  }
  const { context, wardrobe, valuesByLabel, character } = promptModel;
  const value = label => firstStructuredValue(valuesByLabel, [label]);
  const slots = extractCharacterSlots(character);
  if (isCharacterProfileSubject(context.subject)) {
    const groups = buildCharacterCardProfileGroups(context.subject, context.locks, wardrobe);
    const identity = [groups.distinctiveFeatures || [groups.facialGeometry, groups.eyeSignature,
      groups.noseSignature, groups.mouthSignature].filter(Boolean).join(', '), groups.skinSignature, groups.makeup]
      .filter(Boolean).map(naturalIdentity);
    const hair = compactAiCharacterCardHairText(groups.hair, buildCharacterCardHairVariantText(context.subject, context.locks));
    return naturalSentence(['A 20-year-old adult East Asian woman', ...identity, hair, value('Expression')].filter(Boolean).join(', '));
  }
  if (isDedicatedSpecialSubject(context.subject)) {
    const source = buildMidjourneySpecialSubjectPrompt(context.subject, context);
    const identity = context.subject.id === 'european-knight'
      ? 'A realistic adult female medieval European knight'
      : context.subject.id === 'sengoku-samurai' ? 'A realistic adult female Japanese Sengoku samurai' : naturalIdentity(source);
    return naturalSentence([identity, value('Hairstyle'), value('Hair Color'), value('Expression')].filter(Boolean).join(', '));
  }
  if (context.subject.count === 2) {
    const roles = [1, 2].map(index => ['Facial Features', 'Skin Details', 'Hairstyle', 'Hair Styling State', 'Hair Color']
      .map(label => compactPromptClauses(value(`Woman ${index} ${label}`).replace(/^woman [12] has\s+/i, ''), 2)).filter(Boolean));
    const shared = roles[0].filter(part => roles[1].includes(part));
    const bodies = [value('Woman 1 Body Type') ? midjourneyBodyDescription(slots.bodyTypeA) : '',
      value('Woman 2 Body Type') ? midjourneyBodyDescription(slots.bodyTypeB) : ''];
    const bodyText = bodies[0] && bodies[0] === bodies[1]
      ? `Both women have ${bodies[0][0].toLowerCase()}${bodies[0].slice(1)}`
      : [bodies[0] ? midjourneyBodyDescription(slots.bodyTypeA, 'a') : '',
        bodies[1] ? midjourneyBodyDescription(slots.bodyTypeB, 'b') : ''].filter(Boolean).join(' ');
    return [applyDefaultEthnicity('Two 20-year-old adult women.', context.defaultEthnicity), ...[1, 2].map(index => {
      const description = roles[index - 1].filter(part => !shared.includes(part)).join(', ');
      return description ? naturalSentence(`The ${index === 1 ? 'first' : 'second'} woman has ${description}`) : '';
    }), shared.length ? naturalSentence(`Both have ${shared.join(', ')}`) : '', naturalSentence(value('Duo Expression')),
    bodyText].filter(Boolean).join(' ');
  }
  const facialItem = extractCharacterSlots(character).facialFeatures;
  const face = [compactPromptClauses(facialItem?.mj?.face || value('Facial Features'), 3),
    compactPromptClauses(value('Expression'), 1)].filter(Boolean).join(', ');
  const hair = [compactPromptClauses(value('Hairstyle'), 1), compactPromptClauses(value('Hair Styling State'), 1), compactPromptClauses(value('Hair Color'), 1)].filter(Boolean).join(', ');
  const specialSource = value('Special Outfit') || buildSpecialOutfitPrompt(extractWardrobeSlots(wardrobe).specialOutfit);
  const specialPerson = extractAiSpecialPersonFragments(specialSource, context)
    .map(naturalIdentity).filter(Boolean).join(', ');
  return [naturalSentence(context.characterProfilePrompt ? naturalIdentity(context.characterProfilePrompt) : applyDefaultEthnicity('A 20-year-old adult woman', context.defaultEthnicity)),
    naturalSentence([face, compactPromptClauses(value('Skin Details'), 1), hair, specialPerson].filter(Boolean).join(', ')),
    !context.characterProfilePrompt && value('Body Type') ? midjourneyBodyDescription(slots.bodyType) : ''].filter(Boolean).join(' ');
}

function renderMainNaturalMidjourney(promptModel, sceneMirrorReflectionText) {
  const { context, character, valuesByLabel } = promptModel;
  const adaptation = buildMidjourneyFramingPoseAdaptation(context);
  const duo = context.subject.count === 2 && !isSpecialSubject(context.subject);
  let clothing;
  if (duo) {
    const roles = ['a', 'b'].map(role => buildNaturalMjWardrobe(promptModel, role).split(', ').filter(Boolean));
    const shared = roles[0].filter(name => roles[1].includes(name));
    clothing = [...roles.map((names, index) => naturalWardrobeSentence(
      names.filter(name => !shared.includes(name)).join(', '), `The ${index === 0 ? 'first' : 'second'} woman`)),
    naturalWardrobeSentence(shared.join(', '), 'Both')].filter(Boolean).join(' ');
  } else clothing = naturalWardrobeSentence(buildNaturalMjWardrobe(promptModel));
  const stationFixed = isStationFixedSet(context.fixedCompositionSet) || isStationFixedSet(context.stationFixedSceneSource)
    || isCarriageFixedSet(context.fixedCompositionSet) || isCarriageFixedSet(context.carriageFixedSceneSource);
  const style = context.style && !isNoneLikeItem(context.style) ? compactPromptClauses(context.style.en, 5) : '';
  // Restore selected style/film in main MJ while preserving the optical policy.
  const optics = buildAiFreedomImagingSentence(valuesByLabel, { adaptation, sceneIntegrated: true, stationFixed });
  const film = compactPromptClauses(firstStructuredValue(valuesByLabel, ['Camera / Film']), 6);
  return renderNaturalMidjourney({
    imageType: context.observationCapture ? context.imageTypePreset.en : buildMidjourneyImageTypePromptLine(context),
    composition: joinCompositionPromptText(ensureTerminalPeriod(buildCompositionPromptLine(context, { adaptation })), extractCharacterSlots(character).poseComposer),
    subject: buildNaturalMjSubject(promptModel),
    pose: duo ? buildAiDuoDirectSentence(buildAiDuoPoseText(valuesByLabel)) : buildAiFreedomPoseSentence(context, character),
    wardrobe: clothing,
    scene: [buildAiFreedomSceneWithLightingSentence(valuesByLabel, context), naturalSentence(sceneMirrorReflectionText)].filter(Boolean).join(' '),
    imaging: [naturalSentence(style), optics, naturalSentence(film)].filter(Boolean).join(' '),
  });
}

function buildPrompts(context, character, wardrobe, wardrobeColors, lightDirection, film, opticalEffect) {
  const compositionVisibility = getCompositionVisibilityProjection(context);
  const poseComposer = extractCharacterSlots(character).poseComposer;
  const projectionContext = {
    ...context,
    compositionVisibility,
  };
  const projectedCanonicalPoseText = buildProjectedCanonicalPoseText(projectionContext, poseComposer);
  const fixedCompositionPromptProjection = createFixedCompositionPromptProjection({
    compositionVisibility,
    wardrobe,
    wardrobeColors,
    projectedCanonicalPoseText,
    fixedCompositionSet: projectionContext.fixedCompositionSet,
    fixedSetPosition: projectionContext.fixedSetPosition,
    fixedSetBackgroundState: projectionContext.fixedSetBackgroundState,
    fixedSetCaptureMode: projectionContext.fixedSetCaptureMode,
    fixedSetPerformanceState: projectionContext.fixedSetPerformanceState,
    angle: projectionContext.angle,
    orbit: projectionContext.orbit,
  });
  const fixedScene = fixedCompositionPromptProjection?.scene;
  const rendererContext = {
    ...projectionContext,
    ...(fixedScene
      ? {
          fixedCompositionSet: fixedScene.fixedCompositionSet,
          fixedSetPosition: fixedScene.fixedSetPosition,
          fixedSetBackgroundState: fixedScene.fixedSetBackgroundState,
          fixedSetCaptureMode: fixedScene.fixedSetCaptureMode,
          fixedSetPerformanceState: fixedScene.fixedSetPerformanceState,
          angle: fixedScene.angle,
          orbit: fixedScene.orbit,
        }
      : {}),
    projectedCanonicalPoseText: fixedCompositionPromptProjection?.pose.canonicalText
      ?? projectedCanonicalPoseText,
    fixedCompositionPromptProjection,
  };
  const mainContext = {
    ...rendererContext,
    subject: isCharacterProfileSubject(rendererContext.subject)
      ? projectCharacterProfileSubject(rendererContext.subject, compositionVisibility)
      : rendererContext.subject,
    projectedScene: buildProjectedScene(rendererContext),
  };
  const projectedCharacter = projectBodyTypeCharacter(character, mainContext);
  const rendererWardrobe = projectUnderbustTopFit(projectClosedOuterwearWardrobe(projectOuterwearStyling(projectTopHemOverlap(projectAudioForFraming(fixedCompositionPromptProjection?.wardrobe.items || wardrobe, mainContext), mainContext), getCompositionVisibilityProjection(mainContext))), getCompositionVisibilityProjection(mainContext));
  const rendererWardrobeColors = fixedCompositionPromptProjection?.wardrobe.colors || wardrobeColors;
  const promptModel = {
    ...buildStructuredPromptSections(mainContext, projectedCharacter, rendererWardrobe, rendererWardrobeColors, lightDirection, film),
    context: mainContext,
    character: projectedCharacter,
    wardrobe: rendererWardrobe,
    wardrobeColors: rendererWardrobeColors,
    lightDirection,
    film,
    opticalEffect,
  };
  const fullBodyCharacterPromptModel = buildFixedFramingDerivedPromptModel({
    sourcePromptModel: promptModel,
    sourceContext: context.observationCapture ? { ...context, observationCapture: null, locks: { ...context.locks, captureMode: 'standard' } } : context,
    preset: FIXED_FRAMING_DERIVED_PROMPT_PRESETS.fullBodyCharacter,
    character,
    wardrobe,
    wardrobeColors,
    lightDirection,
    film,
  });
  const chestUpPortraitPromptModel = buildFixedFramingDerivedPromptModel({
    sourcePromptModel: promptModel,
    sourceContext: context,
    preset: FIXED_FRAMING_DERIVED_PROMPT_PRESETS.chestUpPortrait,
    character,
    wardrobe,
    wardrobeColors,
    lightDirection,
    film,
  });
  // Main GPT/Z and the same-state GPT chest share the authored ambient source.
  // MJ and excluded subjects/modes retain the original structured source.
  const ambientPose = extractCharacterSlots(projectedCharacter).poseComposer;
  const ambientAnchor = getPoseComposerOption(POSE_COMPOSER_ANCHOR_OPTIONS, ambientPose?.meta?.poseAnchorId);
  const ambientEligible = mainContext.subject.count === 1
    && !isDedicatedSpecialSubject(mainContext.subject) && !isCharacterProfileSubject(mainContext.subject)
    && !mainContext.characterProfilePrompt && !isFixedCompositionSetActive(mainContext.fixedCompositionSet)
    && !(ambientPose?.meta?.poseBaseId === 'lying' && ambientPose?.meta?.poseOrientationId === 'lying-supine'
      && (ambientAnchor?.meta?.supineSurfaceLed === true || ambientPose?.meta?.supineGroundOnly === true));
  const ambientLightDescription = ambientEligible ? resolveAmbientLightDescription(mainContext.lighting) : null;
  const ambientValues = new Map(promptModel.valuesByLabel);
  if (ambientLightDescription) ambientValues.set('Ambient Light Conditions', [`${renderAmbientLightDescription(ambientLightDescription)}.`]);
  const ambientPromptModel = ambientLightDescription
    ? { ...promptModel, valuesByLabel: ambientValues, ambientLightDescription } : promptModel;
  // GPT keeps full source and section order; only reviewed Scene/Lighting
  // visibility is projected. Never pass this renderer-local view to Z/MJ.
  const gptPromptModel = ambientEligible ? projectGptSceneLightingModel(ambientPromptModel) : ambientPromptModel;
  const sceneMirrorReflectionText = ambientEligible
    ? buildBathroomVanityMirrorReflectionText(mainContext)
    : '';
  const grokPrompt = renderGptPrompt(gptPromptModel, {
    compositionSection: true,
    cameraSpatial: ambientEligible,
    sceneMirrorReflectionText,
  });
  const zImagePrompt = renderZImagePrompt(ambientPromptModel, { sceneMirrorReflectionText });
  const midjourneyPrompt = appendMidjourneyParameterTail(
    renderMainNaturalMidjourney(promptModel, sceneMirrorReflectionText),
    {
      ...context.locks,
      aspectRatio: context.aspectRatio.id,
      framingAspectRatio: midjourneyFramingAspectRatio(context.compositionVisibility?.bucket),
    },
  );
  const chestUpPortraitPrompt = renderFixedFramingDerivedPrompt(
    ambientEligible ? projectGptSceneLightingModel({
      ...chestUpPortraitPromptModel,
      ambientLightDescription,
    }) : chestUpPortraitPromptModel,
    FIXED_FRAMING_DERIVED_PROMPT_PRESETS.chestUpPortrait,
    { cameraSpatial: ambientEligible, sceneMirrorReflectionText },
  );
  const fullBodyCharacterPrompt = !context.referencePersonPreview && context.importedCapturePerson
    ? context.importedCapturePerson.fullBodyPrompt : renderFullBodyCharacterPrompt(fullBodyCharacterPromptModel);
  const nanoBananaPrompt = renderNanoBananaPrompt(gptPromptModel, {
    cameraSpatial: ambientEligible, sceneMirrorReflectionText,
  });

  // Repair assembly punctuation only; visual content is unchanged.
  return {
    midjourneyPrompt: polishPublicPromptText(midjourneyPrompt),
    grokPrompt: polishPublicPromptText(grokPrompt),
    zImagePrompt: polishPublicPromptText(zImagePrompt),
    chestUpPortraitPrompt: polishPublicPromptText(chestUpPortraitPrompt),
    fullBodyCharacterPrompt: polishPublicPromptText(fullBodyCharacterPrompt),
    nanoBananaPrompt: polishPublicPromptText(nanoBananaPrompt),
  };
}

