    waistAccessoryBId: wardrobeSlots.waistAccessoryB?.id?.replace(/:b$/, '') || preserveHiddenWaistSelection(null, 'waistAccessoryBId'),
  };
  // Keep an explicit silence choice even when its parent item is absent or cropped.
  for (const control of getLockControls()) {
    if (!/^(bodyType|hairStylingState)[AB]?Id$|^outerwear[AB]?OpeningId$|^eyewear[AB]?PlacementId$/.test(control.key)) continue;
    const locked = control.options?.find((option) => option.id === context.locks?.[control.key]);
    if (locked && isNoneLikeItem(locked)) resolvedSelection[control.key] = locked.id;
  }
  const storedAction = getSpecifiedAction(context.rawLocks, { ignoreOwners: true });
  if (storedAction) {
    for (const key of ['specifiedActionId', 'specifiedActionSceneRestore', 'poseBaseId', 'poseOrientationId',
      'poseArrangementId', 'poseHandId', 'posePropId', 'poseAnchorId', 'actionPoseCardId',
      ...(storedAction.ownsExpression ? ['expressionId'] : []), ...(storedAction.ownsHead ? ['poseHeadId'] : [])]) {
      resolvedSelection[key] = context.rawLocks[key];
    }
    resolvedSelection.specifiedActionId = storedAction.id;
  }
  // Lying library P3: keep the user's raw angle and orbit for a later cancel, and
  // record the resolved lying camera; an unused 全無 keeps old snapshots' shape.
  if (context.lyingActionActive) {
    resolvedSelection.angleId = context.rawLocks.angleId;
    resolvedSelection.orbitId = context.rawLocks.orbitId;
  }
  resolvedSelection.lyingCameraId = context.lyingCamera?.id || context.rawLocks.lyingCameraId || 'none';
  // expression-pose-v2 P4: record resolved gaze and gesture (raw choice when unused)
  // and the 拍攝方式; unused defaults keep old snapshots' shape.
  const { gaze, gesture, prop } = context.poseResolution || {};
  resolvedSelection.gazeId = gaze ? gaze.id : context.rawLocks.gazeId || 'none';
  resolvedSelection.gestureId = gesture ? gesture.id : context.rawLocks.gestureId || 'none';
  resolvedSelection.propId = prop ? prop.id : context.rawLocks.propId || 'none';
  resolvedSelection.headPostureId = context.poseResolution?.posture?.id || context.rawLocks.headPostureId || 'none';
  resolvedSelection.captureStyleId = context.rawLocks.captureStyleId || 'standard';
  const snapshot = createSelectionSnapshot(LOCK_DEFINITIONS, resolvedSelection);
  if (!snapshot.lyingCameraId || snapshot.lyingCameraId === 'none') delete snapshot.lyingCameraId;
  for (const [key, unused] of [['gazeId', 'none'], ['gestureId', 'none'], ['propId', 'none'], ['headPostureId', 'none'], ['captureStyleId', 'standard']]) {
    if (!snapshot[key] || snapshot[key] === unused) delete snapshot[key];
  }
  if (!storedAction) {
    // Old results keep their exact selection shape. Missing additive fields
    // restore to the new defaults without a compatibility migration.
    delete snapshot.specifiedActionId;
    delete snapshot.specifiedActionSceneRestore;
  }
  if (context.observationCapture) {
    for (const key of [...CAPTURE_OWNED_KEYS, 'specifiedActionSceneRestore']) snapshot[key] = context.rawLocks[key];
    snapshot.captureMode = 'observation';
    snapshot.observationCapture = resolveCapture(context.rawLocks.observationCapture).profile;
    if (context.importedCapturePerson) {
      for (const key of Object.keys(context.rawLocks).filter(isImportedPersonKey)) snapshot[key] = context.rawLocks[key];
      for (const key of ['characterProfileId', 'characterCardHairVariantId', 'characterCardEyewearMode', 'characterCardWardrobeMode', 'characterCardWardrobeLayerIds', 'characterCardPromptOverride']) snapshot[key] = context.rawLocks[key];
    }
  } else { delete snapshot.captureMode; delete snapshot.observationCapture; }
  return snapshot;
}

export function buildLocksFromPrompt(prompt, keepKeys = []) {
  const base = createEmptyLocks();
  REQUIRED_LOCK_KEYS.forEach((key) => {
    base[key] = prompt.selection?.[key] || base[key];
  });
  keepKeys.forEach((key) => {
    base[key] = prompt.selection?.[key] || '';
  });
  return base;
}

function generateSinglePrompt(index, inputLocks, runtime, runtimeOptions = {}) {
  const lockControls = runtime.controls;
  // expression-pose-v2 P4: a selfie 拍攝方式 becomes its selfie hand or prop lock.
  const requestedLocks = applyCaptureStyleLocks(inputLocks);
  const capture = requestedLocks.captureMode === 'observation' ? resolveCapture(requestedLocks.observationCapture) : null;
  if (capture && (capture.error || captureEligibility(requestedLocks, lockControls))) return null;
  let captureRandomState = 1977;
  const random = capture ? () => { captureRandomState = (Math.imul(captureRandomState, 1664525) + 1013904223) >>> 0; return captureRandomState / 4294967296; } : normalizeRandom(runtimeOptions.random);
  // expression-pose-v2 P2: 隨機 becomes one concrete library action before any
  // other resolution, so the result, snapshot and Saved Card all name it.
  const locks = capture ? requestedLocks : resolveRandomSpecifiedAction(requestedLocks, random, { cameraControls: lockControls });
  const importedCapturePerson = capture ? activeImportedPerson(locks) : null;
  const generationLocks = capture ? captureEffectiveLocks(locks) : locks;
  const previewRerollExclusions = buildPreviewRerollExclusions(runtimeOptions.excludePreviousSelection);
  const withPreviewExclusions = (picker, lockedId, exclusionKeys) => (candidates, pickerRandom) => {
    const shouldExcludePrevious = !lockedId || isRandomLockValue(lockedId);
    const eligibleCandidates = shouldExcludePrevious
      ? previewRerollExclusions.filterCandidates(candidates, exclusionKeys)
      : candidates;
    return picker(eligibleCandidates, pickerRandom);
  };
  const pickLocked = (list, lockedId, predicate = () => true, picker = sample, exclusionKeys = []) => (
    pickWithLock(
      list,
      lockedId,
      predicate,
      withPreviewExclusions(picker, lockedId, exclusionKeys),
      random,
    )
  );
  const pickCompatible = (list, lockedId, predicate = () => true, picker = sample, exclusionKeys = []) => (
    pickWithCompatibleLock(
      list,
      lockedId,
      predicate,
      withPreviewExclusions(picker, lockedId, exclusionKeys),
      random,
    )
  );
  const effectiveLocks = sanitizeLocksForCloseupMode(getSpecifiedActionEffectiveLocks(fixedScenePoseLocks(generationLocks), { cameraControls: lockControls }), lockControls);
  if (isFullyClosedOpening(effectiveLocks.outerwearOpeningId) && effectiveLocks.poseHandId === PULL_OPEN_HAND_ID) {
    effectiveLocks.poseHandId = 'none';
  }
  // Lying library P3: a lying action replaces the standing-based angle and orbit
  // with the lying camera (one random() call only when 隨機 is chosen).
  const lyingActionActive = isLyingAction(getSpecifiedAction(effectiveLocks));
  const lyingCamera = lyingActionActive ? resolveLyingCamera(effectiveLocks.lyingCameraId, random) : null;
  if (lyingActionActive) {
    for (const key of ['angleId', 'orbitId']) effectiveLocks[key] = getControlOptionByZh(lockControls, key, '全無')?.id || '';
  }
  const supineSurfaceOnly = isSupinePoseSelection(effectiveLocks);
  const selectedFixedCompositionSet = getFixedCompositionSetOption(effectiveLocks.fixedCompositionSetId);
  const fixedCompositionSetActive = isFixedCompositionSetActive(selectedFixedCompositionSet) && effectiveLocks.subjectCount !== '2';
  const fixedSetCameraVariationActive = fixedCompositionSetActive && fixedCompositionSetAllowsCameraVariation(selectedFixedCompositionSet);
  if (fixedCompositionSetActive) {
    effectiveLocks.sceneAttributeId = '';
    effectiveLocks.importedWorldSceneMode = 'none';
    effectiveLocks.importedWorldSceneLabel = '';
    effectiveLocks.importedWorldSceneArchitectureText = '';

    ['locationId', 'framingId', 'lensId', 'opticalEffectId'].filter(key =>
      !(key === 'lensId' && fixedSetAllowsLensVariation(selectedFixedCompositionSet))
      && !(key === 'framingId' && fixedSetAllowsFramingVariation(selectedFixedCompositionSet))).forEach((key) => {
      const noneOption = getControlOptionByZh(lockControls, key, '全無');
      effectiveLocks[key] = noneOption?.id || '';
    });
    if (!fixedSetCameraVariationActive) {
      ['angleId', 'orbitId'].forEach((key) => {
        const noneOption = getControlOptionByZh(lockControls, key, '全無');
        effectiveLocks[key] = noneOption?.id || '';
      });
    }

    const requestedStyle = getControlOptionById(lockControls, 'styleId', locks.styleId);
    if (requestedStyle) effectiveLocks.styleId = requestedStyle.id;
  } else {
    effectiveLocks.fixedCompositionSetId = 'none';
    effectiveLocks.fixedSetPositionId = 'none';
    effectiveLocks.fixedSetBackgroundStateId = 'none';
    effectiveLocks.fixedSetCaptureModeId = 'photographer-shot';
    effectiveLocks.fixedSetPerformanceStateId = 'model-natural';
  }
  const hasImportedWorldSceneArchitecture = effectiveLocks.importedWorldSceneMode === 'architecture'
    && Boolean(effectiveLocks.importedWorldSceneArchitectureText);
  if (hasImportedWorldSceneArchitecture) {
    const noneLocation = getControlOptionByZh(lockControls, 'locationId', '全無');
    effectiveLocks.locationId = noneLocation?.id || '';
    effectiveLocks.sceneAttributeId = '';
  }
  const specialSubject = getSpecialSubjectOption(effectiveLocks.specialSubjectId);
  const characterProfile = getCharacterProfileOption(effectiveLocks.characterProfileId);
  const dedicatedSubject = characterProfile || specialSubject;
  const subject = dedicatedSubject || getSubjectOption(effectiveLocks.subjectCount);
  const imageTypePreset = getImageTypePresetOption(effectiveLocks.imageTypePresetId);
  const hasWardrobeLocks = !dedicatedSubject && hasEffectiveWardrobeLockValues(effectiveLocks, lockControls);
  const hasSceneLocks = !supineSurfaceOnly && Boolean(effectiveLocks.locationId || effectiveLocks.sceneAttributeId);
  const aspectRatio = getAspectRatioOption(effectiveLocks.aspectRatio, random, previewRerollExclusions);
  const sceneAttribute = getSceneAttributeOption(effectiveLocks.sceneAttributeId);
  const lowFrequencyPicker = (tag) => (candidates) => {
    const regular = candidates.filter((item) => !item.meta.tags?.includes(tag));
    const lowFrequency = candidates.filter((item) => item.meta.tags?.includes(tag));

    if (regular.length > 0 && (lowFrequency.length === 0 || random() < 0.88)) {
      return sample(regular, random);
    }

    return sample(lowFrequency.length > 0 ? lowFrequency : candidates, random);
  };
  const location = supineSurfaceOnly
    ? SCENE_NONE_LOCATION_OPTION
    : pickLocked(
      runtime.flatCatalog.locations,
      effectiveLocks.locationId,
      (item) => locationMatchesSceneAttribute(item, sceneAttribute),
      sample,
      ['locationId'],
    );
  let style = pickLocked(
    runtime.flatCatalog.regional,
    effectiveLocks.styleId,
    (item) => styleFitsLocation(item, location),
    sample,
    ['styleId'],
  );
  const lockedSpecialAction = effectiveLocks.specialActionId
    ? findById(getByKey(runtime.catalog.character, '特殊動作 (Special Actions)'), effectiveLocks.specialActionId)
    : null;
  const lockedPoseComposerAction = getPoseComposerActionConstraint(effectiveLocks);
  const lockedActionPoseCard = effectiveLocks.actionPoseCardId && subject.count === 1 && !isDedicatedSpecialSubject(subject)
    ? getActionPoseCardById(effectiveLocks.actionPoseCardId)
    : null;
  const lockedActionPose = lockedActionPoseCard?.mode === 'single'
    ? {
        zh: lockedActionPoseCard.title,
        en: lockedActionPoseCard.actionPrompt,
        meta: {
          ...(lockedActionPoseCard.meta || {}),
          tags: withTags(lockedActionPoseCard.meta?.tags || ['action_pose', 'full_body_action']),
        },
      }
    : null;
  const lockedActionConstraint = mergeActionConstraints(lockedSpecialAction, lockedPoseComposerAction, lockedActionPose);
  const framingOptions = capture
    ? runtime.flatCatalog.framing.filter(item => item.zh === '全無' || /全身鏡頭|中景鏡頭|牛仔/.test(item.zh))
    : effectiveLocks.framingId
    ? runtime.flatCatalog.framing
    : getRandomMainFramingOptions(runtime.flatCatalog.framing);
  const framing = pickLocked(
    framingOptions,
    effectiveLocks.framingId,
    (item) => (
      (!lockedActionConstraint || item.zh !== '全無')
      &&
      !((location?.meta?.tags || []).includes('club') && item.meta.visibility === 'close')
      && (effectiveLocks.framingId || (!hasWardrobeLocks && !hasSceneLocks) || item.meta.visibility !== 'close')
      && framingSupportsSubject(item, subject, aspectRatio)
      && specialActionSupportsFraming(lockedActionConstraint, item)
    ),
    sample,
    ['framingId'],
  );
  const fixedFramingCompositionOpening = resolveEdgePortraitCompositionOpening(framing, random);
  const expressionOptions = getByKey(runtime.catalog.character, CHARACTER_EXPRESSION_CATEGORY);
  const lockedDuoExpression = subject.count === 2 && effectiveLocks.duoExpressionId
    ? getDuoExpressionOption(effectiveLocks.duoExpressionId)
    : null;
  const lockedExpressions = [
    lockedDuoExpression,
    !lockedDuoExpression && subject.count === 2 && effectiveLocks.expressionAId ? findById(expressionOptions, effectiveLocks.expressionAId) : null,
    !lockedDuoExpression && subject.count === 2 && effectiveLocks.expressionBId ? findById(expressionOptions, effectiveLocks.expressionBId) : null,
    effectiveLocks.expressionId ? findById(expressionOptions, effectiveLocks.expressionId) : null,
  ].filter(Boolean);
  const pickCameraWithExpressionLock = lockedExpressions.length > 0 ? pickCompatible : pickLocked;
  const specifiedCameraAction = getSpecifiedAction(effectiveLocks);
  const lockedAngle = findById(runtime.flatCatalog.angle, effectiveLocks.angleId);
  const suppressHeadDominantAngle = isHeadDominantFraming(framing) && !headDominantAngleAllowed(lockedAngle);
  const angleLockId = suppressHeadDominantAngle
    ? runtime.flatCatalog.angle.find(isNoneLikeItem)?.id : effectiveLocks.angleId;
  const unspecifiedFramingAllowsAngle = isNoneLikeItem(framing)
    && (!fixedCompositionSetActive || isStationFixedSet(selectedFixedCompositionSet));
  const angle = pickCameraWithExpressionLock(
    runtime.flatCatalog.angle,
    angleLockId,
    (item) => (unspecifiedFramingAllowsAngle || framingSupportsAngle(framing, item))
      && lockedExpressions.every((expression) => angleSupportsExpression(item, expression))
      && specifiedActionSupportsCamera(specifiedCameraAction, 'angleId', item),
    lowFrequencyPicker('low_frequency_angle'),
    ['angleId'],
  );
  // expression-pose-v2 P4 (Cooper option B): an explicit non-回眸 gaze steers an
  // unlocked orbit away from back views; a locked orbit is never replaced.
  const gazeKeepsFrontOrbit = subject.count === 1 && !capture && !specifiedCameraAction?.ownsHead
    && gazeAvoidsBackView(effectiveLocks.gazeId) && (!effectiveLocks.orbitId || isRandomLockValue(effectiveLocks.orbitId));
  let orbit = pickCameraWithExpressionLock(
    runtime.flatCatalog.orbit,
    effectiveLocks.orbitId,
    (item) => framingSupportsOrbit(framing, item) && lockedExpressions.every((expression) => orbitSupportsExpression(item, expression)) && specialActionSupportsOrbit(item, lockedActionConstraint) && specifiedActionSupportsCamera(specifiedCameraAction, 'orbitId', item)
      && !(gazeKeepsFrontOrbit && isBackViewOrbit(item)),
    sample,
    ['orbitId'],
  );
  if (fixedCompositionSetActive && isCarriageFixedSet(selectedFixedCompositionSet)) {
    orbit = resolveCarriageOrbit(selectedFixedCompositionSet, orbit, runtime.flatCatalog.orbit);
  }
  const lens = pickLocked(runtime.flatCatalog.lens, effectiveLocks.lensId, () => true, sample, ['lensId']);
  const apertureLockId = effectiveLocks.apertureId || getControlOptionByZh(lockControls, 'apertureId', '全無')?.id || '';
  const shutterLockId = effectiveLocks.shutterId || getControlOptionByZh(lockControls, 'shutterId', '全無')?.id || '';
  const aperture = pickLocked(runtime.flatCatalog.aperture, apertureLockId, () => true, sample, ['apertureId']);
  const shutter = pickLocked(runtime.flatCatalog.shutter, shutterLockId, () => true, sample, ['shutterId']);
  const transitFixedLighting = fixedCompositionSetActive
    && (isStationFixedSet(selectedFixedCompositionSet) || isCarriageFixedSet(selectedFixedCompositionSet));
  const fixedSetLightingCompatibilityAnchor = fixedCompositionSetActive
    && (transitFixedLighting || selectedFixedCompositionSet?.meta?.tags?.includes('outdoor'))
    ? selectedFixedCompositionSet
    : null;
  const locationForLightingCompatibility = supineSurfaceOnly
    ? null
    : fixedSetLightingCompatibilityAnchor || (hasImportedWorldSceneArchitecture ? null : location);
  // Transit sets honor explicit lighting like ordinary scenes. Random picks
  // use the actual fixed scene above; legacy fixed-set policy stays intact.
  const pickLighting = (!fixedCompositionSetActive || transitFixedLighting) && effectiveLocks.lightingId && !isRandomLockValue(effectiveLocks.lightingId)
    ? pickLocked
    : pickCompatible;
  const lighting = pickLighting(
    runtime.flatCatalog.lighting,
    effectiveLocks.lightingId,
    (item) => (locationForLightingCompatibility ? locationSupportsLighting(locationForLightingCompatibility, item) : true),
    sample,
    ['lightingId'],
  );
  const pickLightDirection = (!fixedCompositionSetActive || transitFixedLighting) && effectiveLocks.lightDirectionId && !isRandomLockValue(effectiveLocks.lightDirectionId)
    ? pickLocked
    : pickCompatible;
  const lightDirection = !lighting
    ? null
    : pickLightDirection(
      runtime.flatCatalog.lightDirection,
      effectiveLocks.lightDirectionId,
      (item) => lightDirectionSupportsScene(item, framing, locationForLightingCompatibility, lighting),
      sample,
      ['lightDirectionId'],
    );
  const imagingLockId = effectiveLocks.filmId || (CAMERA_PROFILE_OPTION_IDS.has(effectiveLocks.cameraSystemId) ? effectiveLocks.cameraSystemId : '');
  const film = pickLocked(
    runtime.flatCatalog.film,
    imagingLockId,
    () => true,
    lowFrequencyPicker('low_frequency_film'),
    ['filmId', 'cameraSystemId'],
  );
  const cameraSystem = getLegacyCameraSystemFromImaging(film);
  const pickOpticalEffect = effectiveLocks.opticalEffectId && !isRandomLockValue(effectiveLocks.opticalEffectId)
    ? pickLocked
    : pickCompatible;
  const hasExplicitOpticalEffect = effectiveLocks.opticalEffectId
    && !isRandomLockValue(effectiveLocks.opticalEffectId);
  const opticalEffectOptions = hasExplicitOpticalEffect
    ? runtime.flatCatalog.effects
    : getRandomOpticalEffectOptions(runtime.flatCatalog.effects);
  const opticalEffect = pickOpticalEffect(
    opticalEffectOptions,
    effectiveLocks.opticalEffectId,
    (item) => opticalEffectSupportsFilm(item, film),
    sample,
    ['opticalEffectId'],
  );
  const fixedCompositionSet = fixedCompositionSetActive ? selectedFixedCompositionSet : null;
  const fixedSetPosition = fixedCompositionSet
    ? getFixedSetPositionOption(effectiveLocks.fixedSetPositionId, fixedCompositionSet)
    : getFixedSetPositionOption('none');
  const fixedSetBackgroundState = fixedCompositionSet
    ? getFixedSetBackgroundStateOption(effectiveLocks.fixedSetBackgroundStateId, fixedCompositionSet)
    : getFixedSetBackgroundStateOption('none');
  const fixedSetCaptureMode = fixedCompositionSet
    ? getFixedSetCaptureModeOption(effectiveLocks.fixedSetCaptureModeId)
    : getFixedSetCaptureModeOption(supineSurfaceOnly ? 'none' : 'photographer-shot');
  const fixedSetPerformanceState = fixedCompositionSet
    ? getFixedSetPerformanceStateOption(effectiveLocks.fixedSetPerformanceStateId)
    : getFixedSetPerformanceStateOption(supineSurfaceOnly ? 'none' : 'model-natural');
  const compositionVisibility = createCompositionVisibilityProjection(framing, {
    fixedCompositionActive: Boolean(fixedCompositionSet) && !fixedSetAllowsFramingVariation(fixedCompositionSet),
  });
  const context = {
    headDominantSuppressedAngleId: suppressHeadDominantAngle ? effectiveLocks.angleId : '',
    subject,
    imageTypePreset,
    aspectRatio,
    sceneAttribute,
    style,
    cameraSystem,
    location,
    framing,
    fixedFramingCompositionOpening,
    angle,
    orbit,
    lyingCamera,
    lyingActionActive,
    // Shared by reference so context copies report the composer's gaze and gesture.
    poseResolution: {},
    lens,
    aperture,
    shutter,
    opticalEffect,
    fixedCompositionSet,
    fixedSetPosition,
    fixedSetBackgroundState,
    fixedSetCaptureMode,
    fixedSetPerformanceState,
    supineSurfaceOnly,
    compositionVisibility,
    film,
    lighting,
    lightDirection,
    locks: effectiveLocks,
    rawLocks: locks,
    random,
    previewRerollExclusions,
    characterProfilePrompt: String(runtimeOptions.characterProfilePrompt || '').trim(),
  };
  if (capture) Object.assign(context, captureContext(capture.selections), { importedCapturePerson });
  const character = buildCharacter(context, runtime.catalog);
  const defaultEthnicitySlots = extractCharacterSlots(character);
  context.defaultEthnicity = resolveDefaultEthnicity({
    ordinary: !isSpecialSubject(subject) && !subject.reference && !context.characterProfilePrompt,
    count: subject.count,
    facial: defaultEthnicitySlots.facialFeatures,
    facialA: defaultEthnicitySlots.facialFeaturesA,
    facialB: defaultEthnicitySlots.facialFeaturesB,
    isNone: isNoneLikeItem,
  });
  if (context.defaultEthnicity.single || context.defaultEthnicity.duoAll) {
    context.subject = { ...subject, en: applyDefaultEthnicity(subject.en, context.defaultEthnicity) };
  }
  const promptCharacter = applyDefaultEthnicityToCharacter(character, context.defaultEthnicity, {
    facialToken: 'character:五官特徵-facial-features:',
    isNone: isNoneLikeItem,
  });
  if (characterUsesResolvedSelfiePoseHand(character)) {
    const noneOrbit = getControlOptionByZh(lockControls, 'orbitId', '全無');
    orbit = noneOrbit || null;
    context.orbit = orbit;
    effectiveLocks.orbitId = noneOrbit?.id || '';
  }
  const cardLayers = getCharacterCardImportedLayers(subject, effectiveLocks);
  const cardWardrobeMode = getCharacterCardWardrobeMode(effectiveLocks);
  const rawPage1Wardrobe = importedCapturePerson ? [] : isDedicatedSpecialSubject(subject) || (isCharacterProfileSubject(subject) && cardWardrobeMode === 'full-default')
    ? []
    : buildWardrobe({ ...context }, effectiveLocks, runtime);
  const filteredPage1Wardrobe = filterPage1WardrobeForCharacterCardLayers(rawPage1Wardrobe, cardLayers);
  const page1Wardrobe = appendLockedPage1FillersForCharacterCardLayers(filteredPage1Wardrobe, cardLayers, effectiveLocks, lockControls);
  const wardrobe = importedCapturePerson ? structuredClone(importedCapturePerson.wardrobe) : resolveBottomRiseCompatibility([...cardLayers, ...page1Wardrobe]);
  context.wardrobe = wardrobe;
  const wardrobeColors = importedCapturePerson ? structuredClone(importedCapturePerson.wardrobeColors) : buildWardrobeColors(extractWardrobeSlots(wardrobe), effectiveLocks, random);

  const {
    midjourneyPrompt,
    grokPrompt,
    zImagePrompt,
    chestUpPortraitPrompt,
    fullBodyCharacterPrompt,
    nanoBananaPrompt,
  } = buildPrompts(context, promptCharacter, wardrobe, wardrobeColors, context.lightDirection, context.film, context.opticalEffect);
  const summaryFields = buildSummaryFields(context, wardrobe, character, wardrobeColors);

  const prompt = {
    id: `${Date.now()}-${index}-${random().toString(36).slice(2, 8)}`,
    date: new Date().toISOString(),
    summary: buildSummary(summaryFields),
    summaryFields,
    midjourneyPrompt,
    grokPrompt,
    zImagePrompt,
    nanoBananaPrompt,
    extraPrompts: [
      {
        preset: FIXED_FRAMING_DERIVED_PROMPT_PRESETS.chestUpPortrait,
        text: chestUpPortraitPrompt,
      },
      {
        preset: FIXED_FRAMING_DERIVED_PROMPT_PRESETS.fullBodyCharacter,
        text: fullBodyCharacterPrompt,
      },
    ].filter((entry) => entry.text).map(({ preset, text }) => ({
      id: preset.id,
      label: preset.uiLabel,
      text,
    })),
    selection: buildSelectionSnapshot(context, wardrobe, wardrobeColors, character, context.lightDirection, context.film),
    structured: {
      Style: [context.imageTypePreset, context.style].filter(Boolean),
      Character: character,
      Wardrobe: wardrobe,
      Location: [context.location],
      Framing: [context.framing, context.angle, context.orbit].filter(Boolean),
      Lighting: [context.lighting, context.lightDirection].filter(Boolean),
      'Lens & Imaging': [context.lens, context.aperture, context.shutter, context.opticalEffect, context.film].filter(Boolean),
    },
  };
  if (subject.count === 1 && !isSpecialSubject(subject) && !context.characterProfilePrompt) {
    let referenceOutputs;
    registerReferencePersonPreview(prompt, (preview) => {
      if (!referenceOutputs) {
        const slots = extractCharacterSlots(character);
        const performance = [slots.expression, slots.actionPose, slots.poseComposer, slots.pose, slots.specialAction].filter(Boolean);
        const referenceContext = {
          ...context,
          referencePersonPreview: true,
          defaultEthnicity: null,
          subject: { ...subject, en: 'one adult person from the attached reference image' },
          wardrobe: [],
        };
        referenceOutputs = buildPrompts(referenceContext, performance, [], {}, lightDirection, film, opticalEffect);
      }
      const referenceText = text => text ? `${REFERENCE_PERSON_INSTRUCTION}\n\n${text}` : '';
      return {
        ...preview,
        grokPrompt: referenceText(referenceOutputs.grokPrompt),
        zImagePrompt: referenceText(referenceOutputs.zImagePrompt),
        nanoBananaPrompt: referenceText(referenceOutputs.nanoBananaPrompt),
        midjourneyPrompt: appendMidjourneyParameterTail(referenceText(referenceOutputs.midjourneyPrompt), {
          ...preview.selection,
          aspectRatio: context.aspectRatio.id,
          framingAspectRatio: midjourneyFramingAspectRatio(context.compositionVisibility?.bucket),
        }),
        extraPrompts: preview.extraPrompts.map(entry => ({ ...entry, text: referenceText(
          entry.id === 'chest-up-portrait' ? referenceOutputs.chestUpPortraitPrompt
            : referenceOutputs.fullBodyCharacterPrompt,
        ) })),
      };
    });
  }
  if (!capture && subject.count === 1 && !isSpecialSubject(subject) && !context.characterProfilePrompt) {
    const slots = extractCharacterSlots(character);
    registerFullBodyImportSource(prompt, {
      character: ['bodyType', 'facialFeatures', 'skinDetails', 'hairstyle', 'hairStylingState', 'hairColor'].map(key => slots[key]).filter(Boolean),
      wardrobe, wardrobeColors, locks,
    });
  }
  return prompt;
}

export function generatePrompts(count = 1, locks = createEmptyLocks(), customLibrary = [], runtimeOptions = {}) {
  const runtime = getEngineRuntime(customLibrary);
  return Array.from({ length: count }, (_, index) => generateSinglePrompt(index, locks, runtime, runtimeOptions)).filter(Boolean);
}

